'use client'

import { useState, useSyncExternalStore, type ReactNode, type RefObject } from 'react'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { usePanelRef, type PanelImperativeHandle } from 'react-resizable-panels'
import { toast } from 'sonner'
import { EditorProvider, useDocumentRootAttribute, useDocumentRootClass, useEditor, useWindowEvent } from '@mcut/react'
import type { Project } from '@mcut/timeline'
import type { TranscriptResult } from '@mcut/transcription'
import { cn } from '@/lib/utils'
import { ResizableHandle, ResizablePanel, ResizablePanelGroup } from '@/components/ui/resizable'
import { ScrollArea } from '@/components/ui/scroll-area'
import { Toaster } from '@/components/ui/sonner'
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip'
import './editor-default-actions'
import { actionForEvent, isActionEnabled, runEditorAction, type ActionContext } from './action-registry'
import { editorClipboard } from './editor-clipboard'
import { CommandPalette } from './command-palette'
import { CompactWorkspace } from './compact-workspace'
import { EDITOR_LAYOUT_KEYS } from './editor-layout'
import { PanelCard } from './editor-primitives'
import { SessionPersistence, usePersistedLayout } from './editor-session'
import { EditorToolbar } from './editor-toolbar'
import { CurveEditorHost } from './easing-editor'
import { EditorUIProvider, useEditorUI, type EditorTheme, type LeftTab } from './editor-ui'
import { EMBED_OMISSIONS, type EmbedOmission, type EmbedOptions } from './embed'
import { EmbedShell } from './embed-shell'
import { useProjectFontLoader } from './font-library'
import { LEFT_TABS, LeftPanel } from './left-panel'
import { LiveMcpBridge } from './live-mcp-bridge'
import { PreviewArea, TrackSorter } from './preview-area'
import { PropertiesPanel } from './properties-panel'
import { host } from './studio-host'
import { TimelinePanel } from './timeline-panel'
import { UpdateDialog } from './update-dialog'

function isTypingTarget(target: EventTarget | null): target is HTMLElement {
  if (!(target instanceof HTMLElement)) return false
  return target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement || target.isContentEditable
}

function ProjectFontLoader() {
  useProjectFontLoader()
  return null
}

function EditorHotkeys({ omitted }: { omitted: ReadonlySet<EmbedOmission> }) {
  const engine = useEditor()
  const ui = useEditorUI()
  useWindowEvent('keydown', (event) => {
    if (isTypingTarget(event.target)) {
      if (event.key === 'Escape') event.target.blur()
      return
    }
    if (event.key === 'Escape') {
      engine.clearSelection()
      return
    }
    if ((event.metaKey || event.ctrlKey) && !event.shiftKey && event.key.toLowerCase() === 's') {
      event.preventDefault()
      if (!omitted.has('session-persistence')) toast('Autosaved — projects persist in this browser')
      return
    }
    const action = actionForEvent(event)
    if (!action) return
    event.preventDefault()
    const context: ActionContext = { engine, ui, clipboard: editorClipboard }
    if (isActionEnabled(action, context)) runEditorAction(action, context)
  })
  useWindowEvent('mcut:run-action', (event) => {
    runEditorAction(event.detail, { engine, ui, clipboard: editorClipboard })
  })
  return null
}

function subscribeHydration(onStoreChange: () => void): () => void {
  const id = window.setTimeout(onStoreChange, 0)
  return () => window.clearTimeout(id)
}

function clientHydrationSnapshot(): boolean {
  return true
}

function serverHydrationSnapshot(): boolean {
  return false
}

export function useHasHydrated(): boolean {
  return useSyncExternalStore(subscribeHydration, clientHydrationSnapshot, serverHydrationSnapshot)
}

function ChromeRail({ tab, collapsed, onSelect }: { tab: LeftTab; collapsed: boolean; onSelect: (tab: LeftTab) => void }) {
  return (
    <div className="flex w-12 shrink-0 flex-col items-center gap-2">
      {LEFT_TABS.map(({ id, label, icon: Icon }) => (
        <Tooltip key={id}>
          <TooltipTrigger
            render={
              <button
                type="button"
                data-rail-tab={id}
                aria-label={collapsed ? `Show ${label.toLowerCase()}` : label}
                aria-pressed={tab === id && !collapsed}
                className={cn(
                  'flex size-10 items-center justify-center rounded-lg transition-colors',
                  tab === id && !collapsed ? 'bg-card text-foreground shadow-xs' : 'text-muted-foreground hover:bg-foreground/5 hover:text-foreground',
                )}
                onClick={() => onSelect(id)}
              />
            }
          >
            <Icon className="size-5" />
          </TooltipTrigger>
          <TooltipContent side="right">{collapsed ? `Show ${label.toLowerCase()}` : label}</TooltipContent>
        </Tooltip>
      ))}
    </div>
  )
}

function EditorDocumentTheme({ theme }: { theme: EditorTheme }) {
  useDocumentRootAttribute('data-editor', '')
  useDocumentRootAttribute('data-window-chrome', host.windowChrome)
  useDocumentRootClass('dark', theme === 'dark')
  return null
}

export interface EditorShellProps {
  project?: Project
  transcribe?: (audio: Blob) => Promise<TranscriptResult>
  embed?: EmbedOptions
}

type WorkspaceProps = Pick<EditorShellProps, 'transcribe'> & {
  leftPanelRef: RefObject<PanelImperativeHandle | null>
  omitted: ReadonlySet<EmbedOmission>
}

function Workspace({ transcribe, leftPanelRef, omitted }: WorkspaceProps) {
  const { layout } = useEditorUI()
  switch (layout) {
    case 'full':
      return <FullWorkspace transcribe={transcribe} leftPanelRef={leftPanelRef} omitted={omitted} />
    case 'compact':
      return <CompactWorkspace transcribe={transcribe} omitted={omitted} />
    default: {
      const exhaustive: never = layout
      return exhaustive
    }
  }
}

function FullWorkspace({ transcribe, leftPanelRef, omitted }: WorkspaceProps) {
  const { leftTab: tab, setLeftTab: setTab, layoutResetToken } = useEditorUI()
  const panelsReady = useHasHydrated()
  const persistLayout = !omitted.has('session-persistence')
  const verticalLayout = usePersistedLayout(EDITOR_LAYOUT_KEYS.vertical, layoutResetToken, persistLayout)
  const horizontalLayout = usePersistedLayout(EDITOR_LAYOUT_KEYS.horizontal, layoutResetToken, persistLayout)
  const [leftCollapsed, setLeftCollapsed] = useState(false)

  const onRailSelect = (next: LeftTab) => {
    const panel = leftPanelRef.current
    if (panel?.isCollapsed()) {
      panel.expand()
      setTab(next)
      return
    }
    if (next === tab) {
      panel?.collapse()
      return
    }
    setTab(next)
  }

  return (
    <>
      <EditorToolbar />
      <div className="flex min-h-0 flex-1">
        <ChromeRail tab={tab} collapsed={leftCollapsed} onSelect={onRailSelect} />
        {panelsReady ? (
          <TrackSorter>
            <ResizablePanelGroup key={`vertical-${layoutResetToken}`} orientation="vertical" className="min-h-0 flex-1 pr-2 pb-2" {...verticalLayout}>
              <ResizablePanel id="workspace" defaultSize="62%" minSize="30%">
                <ResizablePanelGroup key={`horizontal-${layoutResetToken}`} orientation="horizontal" {...horizontalLayout}>
                  <ResizablePanel
                    id="left"
                    defaultSize="22%"
                    minSize="14%"
                    collapsible
                    panelRef={leftPanelRef}
                    onResize={(size) => setLeftCollapsed(size.asPercentage === 0)}
                  >
                    <LeftPanel tab={tab} transcribe={transcribe} omitted={omitted} />
                  </ResizablePanel>
                  <ResizableHandle className={leftCollapsed ? 'hidden' : undefined} />
                  <ResizablePanel id="preview" defaultSize="56%" minSize="30%">
                    <PreviewArea />
                  </ResizablePanel>
                  <ResizableHandle />
                  <ResizablePanel id="inspector" defaultSize="22%" minSize="14%" collapsible>
                    <PanelCard>
                      <ScrollArea className="h-full scroll-mask-b">
                        <PropertiesPanel />
                      </ScrollArea>
                    </PanelCard>
                  </ResizablePanel>
                </ResizablePanelGroup>
              </ResizablePanel>
              <ResizableHandle />
              <ResizablePanel id="timeline" defaultSize="38%" minSize="18%">
                <PanelCard>
                  <TimelinePanel className="h-full" />
                </PanelCard>
              </ResizablePanel>
            </ResizablePanelGroup>
          </TrackSorter>
        ) : (
          <div className="min-h-0 flex-1 pr-2 pb-2">
            <PanelCard className="flex items-center justify-center text-xs text-muted-foreground">
              <span>Loading editor...</span>
            </PanelCard>
          </div>
        )}
      </div>
    </>
  )
}

function Shell({ omitted, children }: { omitted: ReadonlySet<EmbedOmission>; children: ReactNode }) {
  const { theme } = useEditorUI()
  return (
    <div data-editor="" className={cn('flex h-dvh flex-col overflow-hidden bg-background text-foreground', theme === 'dark' && 'dark')}>
      <EditorDocumentTheme theme={theme} />
      <EditorHotkeys omitted={omitted} />
      <CommandPalette />
      <CurveEditorHost />
      <ProjectFontLoader />
      {children}
      <Toaster position="bottom-right" />
      {host.updates === null ? null : <UpdateDialog updates={host.updates} />}
    </div>
  )
}

export function EditorShell({ project, transcribe, embed }: EditorShellProps) {
  const [queryClient] = useState(() => new QueryClient())
  const leftPanelRef = usePanelRef()
  const omitted: ReadonlySet<EmbedOmission> = new Set(embed ? EMBED_OMISSIONS.map((omission) => omission.id) : [])
  const workspace = <Workspace transcribe={transcribe} leftPanelRef={leftPanelRef} omitted={omitted} />
  return (
    <QueryClientProvider client={queryClient}>
      <EditorProvider {...(project ? { project } : {})}>
        <EditorUIProvider leftPanelRef={leftPanelRef}>
          <TooltipProvider>
            <Shell omitted={omitted}>
              {!omitted.has('session-persistence') && <SessionPersistence />}
              {!omitted.has('live-mcp-bridge') && <LiveMcpBridge />}
              {embed ? <EmbedShell options={embed}>{workspace}</EmbedShell> : workspace}
            </Shell>
          </TooltipProvider>
        </EditorUIProvider>
      </EditorProvider>
    </QueryClientProvider>
  )
}

'use client'

import { useCallback, useMemo, useState } from 'react'
import { useQuery } from '@tanstack/react-query'
import type { GroupProps } from 'react-resizable-panels'
import { toast } from 'sonner'
import { useEditor, useEditorState, useEngineSubscription } from '@mcut/react'
import type { Project } from '@mcut/timeline'
import { Button } from '@/components/ui/button'
import { clearSavedSession, loadSavedSession, requestPersistentStorage, saveProjectSnapshot } from './persistence'

let persistenceRequested = false

function isProjectEmpty(project: Project): boolean {
  return Object.keys(project.assets).length === 0 && project.tracks.every((track) => track.elements.length === 0)
}

export function SessionPersistence() {
  const engine = useEditor()
  const projectEmpty = useEditorState((s) => isProjectEmpty(s.project))
  const [dismissed, setDismissed] = useState(false)
  const saved = useQuery({
    queryKey: ['mcut', 'saved-session'],
    queryFn: loadSavedSession,
    staleTime: Infinity,
    gcTime: Infinity,
    retry: false,
  })

  useEngineSubscription(
    engine.store,
    () => {
      if (!persistenceRequested) {
        persistenceRequested = true
        void requestPersistentStorage()
      }
      saveProjectSnapshot(engine.project).catch(() => {})
    },
    { debounceMs: 800 },
  )

  const session = saved.data
  if (dismissed || !projectEmpty || !session) return null
  return (
    <div
      role="dialog"
      aria-label="Restore previous session"
      className="fixed right-4 bottom-4 z-50 flex items-center gap-3 rounded-lg border bg-popover px-4 py-3 text-sm text-popover-foreground shadow-lg"
    >
      <span>Restore previous session?</span>
      <Button
        size="xs"
        onClick={() => {
          engine.loadProject(session.project)
          if (session.missingAssetIds.length > 0) {
            toast.warning(`${session.missingAssetIds.length} media file(s) could not be restored — re-import them.`)
          }
          setDismissed(true)
        }}
      >
        Restore
      </Button>
      <Button
        size="xs"
        variant="ghost"
        onClick={() => {
          void clearSavedSession()
          setDismissed(true)
        }}
      >
        Discard
      </Button>
    </div>
  )
}

function readPersistedLayout(key: string, resetToken: number): GroupProps['defaultLayout'] | undefined {
  void resetToken
  if (typeof window === 'undefined') return undefined
  try {
    const raw = window.localStorage.getItem(key)
    return raw ? (JSON.parse(raw) as GroupProps['defaultLayout']) : undefined
  } catch {
    return undefined
  }
}

export function usePersistedLayout(key: string, resetToken: number, enabled: boolean): Pick<GroupProps, 'defaultLayout' | 'onLayoutChanged'> {
  const defaultLayout = useMemo(() => (enabled ? readPersistedLayout(key, resetToken) : undefined), [enabled, key, resetToken])
  const onLayoutChanged = useCallback(
    (layout: Parameters<NonNullable<GroupProps['onLayoutChanged']>>[0]) => {
      if (!enabled) return
      try {
        window.localStorage.setItem(key, JSON.stringify(layout))
      } catch {}
    },
    [enabled, key],
  )
  return {
    ...(defaultLayout ? { defaultLayout } : {}),
    onLayoutChanged,
  }
}

'use client'

import { useState } from 'react'
import { toast } from 'sonner'
import { isWebGPUSupported } from '@mcut/compositor'
import { PlayerCanvas, useEditor, useEditorState } from '@mcut/react'
import { getElement } from '@mcut/timeline'
import { EditorDnd } from './editor-dnd'
import { PanelCard } from './editor-primitives'
import { useEditorUI } from './editor-ui'
import { LayoutBank } from './layout-bank'
import { LayoutSlotEditor } from './layout-slot-editor'
import { TextEditOverlay } from './text-edit-overlay'
import { TransportBar } from './transport-bar'

function usePreviewRenderer(): 'canvas2d' | 'webgpu' {
  const [renderer] = useState<'canvas2d' | 'webgpu'>(() => {
    if (typeof window === 'undefined') return 'canvas2d'
    const requested = new URLSearchParams(window.location.search).get('renderer')
    if (requested !== 'webgpu') return 'canvas2d'
    if (!isWebGPUSupported()) {
      setTimeout(() => {
        toast.error('This browser has no WebGPU (needs Chrome 113+, Safari 26+, or Firefox 141+) — using the canvas2d renderer.')
      }, 0)
      return 'canvas2d'
    }
    return 'webgpu'
  })
  return renderer
}

export function PreviewArea() {
  const engine = useEditor()
  const width = useEditorState((s) => s.project.width)
  const height = useEditorState((s) => s.project.height)
  const { mode, previewQuality, editingTextId, setEditingTextId } = useEditorUI()
  const renderer = usePreviewRenderer()
  return (
    <PanelCard className="flex flex-col">
      <div className="flex min-h-0 flex-1">
        {mode === 'multicam' && <LayoutBank />}
        <div className="flex min-h-0 min-w-0 flex-1 items-center justify-center overflow-hidden p-4 [container-type:size]">
          <div
            className="relative w-full"
            style={{
              maxWidth: `min(100%, calc(100cqh * ${width / height} - ${(24 * width) / height}px))`,
              ['--mcut-aspect' as string]: `${width} / ${height}`,
            }}
          >
            <PlayerCanvas
              quality={previewQuality}
              renderer={renderer}
              className="overflow-hidden rounded-lg shadow-xl ring-1 ring-foreground/10"
              {...(editingTextId ? { hiddenElementIds: new Set([editingTextId]) } : {})}
              onElementDoubleClick={(elementId) => {
                const element = getElement(engine.project, elementId)
                if (element?.type === 'text') setEditingTextId(elementId)
              }}
            />
            {mode === 'multicam' && <LayoutSlotEditor />}
            <TextEditOverlay />
          </div>
        </div>
      </div>
      <TransportBar />
    </PanelCard>
  )
}

export function TrackSorter({ children }: { children: React.ReactNode }) {
  const engine = useEditor()
  return (
    <EditorDnd
      onTrackSort={(activeTrackId, overTrackId) => {
        const toIndex = engine.project.tracks.findIndex((t) => t.id === overTrackId)
        if (toIndex === -1) return
        try {
          engine.dispatch({
            type: 'reorderTrack',
            trackId: activeTrackId as `t-${string}`,
            toIndex,
          })
        } catch {}
      }}
    >
      {children}
    </EditorDnd>
  )
}

import { z } from 'zod'

export const embedOptionsSchema = z.object({
  clip: z.string().min(1),
  autoplay: z.boolean(),
  muted: z.boolean(),
})

export type EmbedOptions = z.infer<typeof embedOptionsSchema>

export const EMBED_OMISSIONS = [
  {
    id: 'session-persistence',
    reason:
      "Saving the demo project and panel layout into a visitor's IndexedDB and localStorage would leave homepage state behind with no restore flow on the site.",
    selector: '[aria-label="Restore previous session"]',
  },
  {
    id: 'live-mcp-bridge',
    reason: 'The live bridge is a 127.0.0.1 server in the desktop main process, which the site has no equivalent of.',
  },
  {
    id: 'transcription-key-settings',
    reason:
      'The AssemblyAI key lives in the desktop main process behind safeStorage and IPC. The site has no secret store, so the captions panel has no key field.',
    selector: '[data-slot="transcription-key-field"]',
  },
  {
    id: 'window-chrome',
    reason: 'An iframe has no title bar or traffic lights, so the header renders the browser chrome variant instead of mac or linux.',
    selector: 'html[data-window-chrome]',
  },
] as const satisfies ReadonlyArray<{ id: string; reason: string; selector?: string }>

export type EmbedOmission = (typeof EMBED_OMISSIONS)[number]['id']

export function readEmbedOptions(search: string): EmbedOptions | null {
  const params = new URLSearchParams(search)
  const parsed = embedOptionsSchema.safeParse({
    clip: params.get('clip') ?? '',
    autoplay: params.get('autoplay') === '1',
    muted: params.get('muted') === '1',
  })
  return parsed.success ? parsed.data : null
}

export const parentMessageSchema = z.discriminatedUnion('type', [
  z.object({ type: z.literal('mcut:embed:play') }),
  z.object({ type: z.literal('mcut:embed:pause') }),
  z.object({ type: z.literal('mcut:embed:collapsed'), collapsed: z.boolean() }),
  z.object({ type: z.literal('mcut:embed:request'), request: z.unknown() }),
  z.object({ type: z.literal('mcut:embed:reset') }),
])

export type ParentMessage = z.infer<typeof parentMessageSchema>

export type EmbedMessage =
  | { type: 'mcut:embed:ready' }
  | { type: 'mcut:embed:playing'; playing: boolean }
  | { type: 'mcut:embed:result'; id: string; ok: true; result: unknown }
  | { type: 'mcut:embed:result'; id: string; ok: false; message: string }

export function postToParent(message: EmbedMessage): void {
  if (window.parent === window) return
  window.parent.postMessage(message, window.location.origin)
}

'use client'

import { useQuery } from '@tanstack/react-query'
import { useEditor, useEngineSubscription, useWindowEvent } from '@mcut/react'
import { getElementLocation, getProjectDurationMs, type EditorEngine, type ElementId, type Project } from '@mcut/timeline'
import { preloadMediabunny } from '@mcut/media'
import { z } from 'zod'
import { bridgeRequestSchema } from './bridge-request'
import { elementForAsset, insertElementAtPlayhead } from './editor-actions'
import { parentMessageSchema, postToParent, type EmbedOptions, type ParentMessage } from './embed'
import { useEditorUI } from './editor-ui'
import { handleLiveMcpRequest } from './live-mcp-bridge'
import { importMediaFiles } from './media-import'

declare global {
  interface Window {
    mcutEmbedClip?: Promise<Response>
  }
}

function clipFileName(clip: string): string {
  const last = new URL(clip, window.location.href).pathname.split('/').pop() ?? ''
  return last.length > 0 ? decodeURIComponent(last) : 'clip'
}

async function fetchClipFile(clip: string): Promise<File> {
  const response = await (window.mcutEmbedClip ?? fetch(clip))
  window.mcutEmbedClip = undefined
  if (!response.ok) throw new Error(`Could not load the clip (${response.status})`)
  const blob = await response.blob()
  return new File([blob], clipFileName(clip), { type: blob.type })
}

async function bootstrapEmbed(engine: EditorEngine, options: EmbedOptions): Promise<{ elementId: ElementId; project: Project }> {
  const [file] = await Promise.all([fetchClipFile(options.clip), preloadMediabunny()])
  const [asset] = await importMediaFiles(engine, [file])
  if (!asset) throw new Error('Could not import the clip')
  if (asset.width !== undefined && asset.height !== undefined) {
    engine.dispatch({ type: 'updateProject', width: asset.width, height: asset.height }, { history: false })
  }
  engine.seek(0)
  const elementId = insertElementAtPlayhead(engine, elementForAsset(engine, asset))
  const location = getElementLocation(engine.project, elementId)
  if (options.muted && location) {
    engine.dispatch({ type: 'setTrackFlags', trackId: location.track.id, muted: true }, { history: false })
  }
  engine.loadProject(engine.project)
  engine.seek(0)
  if (options.autoplay) engine.play()
  postToParent({ type: 'mcut:embed:ready' })
  return { elementId, project: engine.project }
}

function requestId(raw: unknown): string {
  const parsed = z.object({ id: z.string() }).safeParse(raw)
  return parsed.success ? parsed.data.id : ''
}

function applyParentMessage(
  engine: EditorEngine,
  ui: ReturnType<typeof useEditorUI>,
  message: ParentMessage,
  onCollapsed: (collapsed: boolean) => void,
  project: Project | undefined,
): void {
  switch (message.type) {
    case 'mcut:embed:play':
      engine.play()
      return
    case 'mcut:embed:pause':
      engine.pause()
      return
    case 'mcut:embed:collapsed':
      onCollapsed(message.collapsed)
      return
    case 'mcut:embed:reset':
      if (!project) return
      engine.pause()
      engine.loadProject(project)
      engine.seek(0)
      engine.play()
      return
    case 'mcut:embed:request': {
      const parsed = bridgeRequestSchema.safeParse(message.request)
      if (!parsed.success) {
        postToParent({
          type: 'mcut:embed:result',
          id: requestId(message.request),
          ok: false,
          message: z.prettifyError(parsed.error),
        })
        return
      }
      const request = parsed.data
      void (async () => {
        try {
          const result = await handleLiveMcpRequest(engine, ui, request)
          postToParent({ type: 'mcut:embed:result', id: request.id, ok: true, result })
        } catch (error) {
          postToParent({
            type: 'mcut:embed:result',
            id: request.id,
            ok: false,
            message: error instanceof Error ? error.message : String(error),
          })
        }
      })()
      return
    }
    default: {
      const unhandled: never = message
      throw new Error(`Unhandled parent message ${JSON.stringify(unhandled)}`)
    }
  }
}

export function EmbedBootstrap({ options, loop, onCollapsed }: { options: EmbedOptions; loop: boolean; onCollapsed: (collapsed: boolean) => void }) {
  const engine = useEditor()
  const ui = useEditorUI()
  const bootstrap = useQuery({
    queryKey: ['mcut', 'embed', options.clip],
    queryFn: () => bootstrapEmbed(engine, options),
    staleTime: Infinity,
    gcTime: Infinity,
    retry: false,
  })
  const project = bootstrap.data?.project

  useEngineSubscription(engine.playback, (state, previous) => {
    if (state.isPlaying === previous.isPlaying) return
    const atEnd = state.currentTimeMs >= getProjectDurationMs(engine.project)
    if (loop && previous.isPlaying && atEnd) {
      engine.seek(0)
      engine.play()
      return
    }
    postToParent({ type: 'mcut:embed:playing', playing: state.isPlaying })
  })

  useWindowEvent('message', (event) => {
    if (event.origin !== window.location.origin) return
    const parsed = parentMessageSchema.safeParse(event.data)
    if (parsed.success) applyParentMessage(engine, ui, parsed.data, onCollapsed, project)
  })

  if (!bootstrap.isError) return null
  return (
    <div role="alert" className="fixed right-4 bottom-4 z-50 rounded-lg border bg-popover px-4 py-3 text-sm text-popover-foreground shadow-lg">
      {bootstrap.error.message}
    </div>
  )
}

'use client'

import { useState, type ReactNode } from 'react'
import type { EmbedOptions } from './embed'
import { EmbedBootstrap } from './embed-bootstrap'

type EmbedView = 'collapsed' | 'expanded'

export function EmbedShell({ options, children }: { options: EmbedOptions; children: ReactNode }) {
  const [view, setView] = useState<EmbedView>('collapsed')
  return (
    <>
      <EmbedBootstrap options={options} loop={view === 'collapsed'} onCollapsed={(collapsed) => setView(collapsed ? 'collapsed' : 'expanded')} />
      {children}
    </>
  )
}

'use client'

import { CaptionsIcon, FolderOpenIcon, SearchIcon, SparklesIcon, TypeIcon } from '@/lib/icons'
import type { TranscriptResult } from '@mcut/transcription'
import { ScrollArea } from '@/components/ui/scroll-area'
import { AnimationsPanel } from './animations-panel'
import { CaptionsPanel } from './captions-panel'
import { PanelCard, PanelHeader, PanelSectionLabel } from './editor-primitives'
import type { LeftTab } from './editor-ui'
import type { EmbedOmission } from './embed'
import { MediaBin } from './media-bin'
import { saveAssetBlob } from './persistence'
import { TextPanel } from './text-panel'
import { TranscriptPanel } from './transcript-panel'

export const LEFT_TABS: Array<{ id: LeftTab; label: string; icon: typeof FolderOpenIcon }> = [
  { id: 'media', label: 'Media', icon: FolderOpenIcon },
  { id: 'text', label: 'Text', icon: TypeIcon },
  { id: 'animate', label: 'Animate', icon: SparklesIcon },
  { id: 'captions', label: 'Captions', icon: CaptionsIcon },
  { id: 'transcript', label: 'Find', icon: SearchIcon },
]

export interface LeftPanelProps {
  tab: LeftTab
  transcribe?: (audio: Blob) => Promise<TranscriptResult>
  omitted: ReadonlySet<EmbedOmission>
}

export function LeftPanel({ tab, transcribe, omitted }: LeftPanelProps) {
  if (tab === 'media') {
    return (
      <PanelCard>
        <MediaBin {...(!omitted.has('session-persistence') ? { onAssetImported: (asset, file) => void saveAssetBlob(asset, file) } : {})} />
      </PanelCard>
    )
  }
  if (tab === 'captions') {
    return (
      <PanelCard>
        <CaptionsPanel transcribe={transcribe} />
      </PanelCard>
    )
  }
  if (tab === 'transcript') {
    return (
      <PanelCard>
        <TranscriptPanel transcribe={transcribe} />
      </PanelCard>
    )
  }
  return (
    <PanelCard className="flex flex-col">
      <PanelHeader>
        <PanelSectionLabel>{tab === 'text' ? 'Text' : 'Animate'}</PanelSectionLabel>
      </PanelHeader>
      <ScrollArea className="min-h-0 min-w-0 flex-1 scroll-mask-b">{tab === 'text' ? <TextPanel /> : <AnimationsPanel />}</ScrollArea>
    </PanelCard>
  )
}

'use client'

import { useState } from 'react'
import { SlidersHorizontalIcon } from '@/lib/icons'
import { cn } from '@/lib/utils'
import { Dialog, DialogContent, DialogTitle } from '@/components/ui/dialog'
import { ScrollArea } from '@/components/ui/scroll-area'
import { PanelCard } from './editor-primitives'
import { EditorToolbar } from './editor-toolbar'
import { useEditorUI, type LeftTab } from './editor-ui'
import { LEFT_TABS, LeftPanel, type LeftPanelProps } from './left-panel'
import { PreviewArea, TrackSorter } from './preview-area'
import { PropertiesPanel } from './properties-panel'
import { TimelinePanel } from './timeline-panel'

type CompactPanel = LeftTab | 'inspector'

type CompactSheet = { open: true; panel: CompactPanel } | { open: false; panel: CompactPanel | null }

const COMPACT_TABS: Array<{ id: CompactPanel; label: string; icon: typeof SlidersHorizontalIcon }> = [
  ...LEFT_TABS,
  { id: 'inspector', label: 'Inspect', icon: SlidersHorizontalIcon },
]

function CompactTabBar({ active, onSelect }: { active: CompactPanel | null; onSelect: (panel: CompactPanel) => void }) {
  return (
    <div data-slot="compact-tab-bar" className="flex h-14 shrink-0 items-stretch gap-1 bg-background px-2 py-1">
      {COMPACT_TABS.map(({ id, label, icon: Icon }) => (
        <button
          key={id}
          type="button"
          data-rail-tab={id}
          aria-pressed={active === id}
          className={cn(
            'flex min-w-11 flex-1 flex-col items-center justify-center gap-0.5 rounded-lg text-2xs font-medium transition-colors',
            active === id ? 'bg-card text-foreground shadow-xs' : 'text-muted-foreground hover:bg-foreground/5 hover:text-foreground',
          )}
          onClick={() => onSelect(id)}
        >
          <Icon className="size-5" />
          {label}
        </button>
      ))}
    </div>
  )
}

function SheetBody({ panel, transcribe, omitted }: { panel: CompactPanel } & Omit<LeftPanelProps, 'tab'>) {
  if (panel === 'inspector') {
    return (
      <PanelCard>
        <ScrollArea className="h-full scroll-mask-b">
          <PropertiesPanel />
        </ScrollArea>
      </PanelCard>
    )
  }
  return <LeftPanel tab={panel} transcribe={transcribe} omitted={omitted} />
}

export function CompactWorkspace({ transcribe, omitted }: Omit<LeftPanelProps, 'tab'>) {
  const { setLeftTab } = useEditorUI()
  const [sheet, setSheet] = useState<CompactSheet>({ open: false, panel: null })
  const active = sheet.open ? sheet.panel : null
  const label = COMPACT_TABS.find((tab) => tab.id === sheet.panel)?.label ?? ''

  const toggleSheet = (panel: CompactPanel) => {
    if (panel === active) {
      setSheet({ open: false, panel })
      return
    }
    if (panel !== 'inspector') setLeftTab(panel)
    setSheet({ open: true, panel })
  }

  return (
    <TrackSorter>
      <div className="flex h-full min-h-0 flex-col">
        <EditorToolbar />
        <div className="min-h-0 flex-1 px-2">
          <PreviewArea />
        </div>
        <div className="basis-[38%] shrink-0 p-2">
          <PanelCard>
            <TimelinePanel className="h-full" />
          </PanelCard>
        </div>
        <CompactTabBar active={active} onSelect={toggleSheet} />
        <Dialog
          open={sheet.open}
          onOpenChange={(open) => {
            if (!open) setSheet({ open: false, panel: sheet.panel })
          }}
        >
          <DialogContent
            data-slot="compact-sheet"
            showCloseButton={false}
            className="top-auto bottom-0 left-0 flex h-[70dvh] w-full max-w-none translate-x-0 translate-y-0 flex-col overflow-hidden rounded-b-none p-0 transition-[opacity,translate,scale] sm:max-w-none data-starting-style:translate-y-4 data-ending-style:translate-y-4"
          >
            <DialogTitle className="sr-only">{label}</DialogTitle>
            <div className="min-h-0 flex-1">{sheet.panel !== null && <SheetBody panel={sheet.panel} transcribe={transcribe} omitted={omitted} />}</div>
            <CompactTabBar active={active} onSelect={toggleSheet} />
          </DialogContent>
        </Dialog>
      </div>
    </TrackSorter>
  )
}

'use client'

import type { ReactNode } from 'react'
import { MoonIcon, Redo2Icon, SunIcon, Undo2Icon } from '@/lib/icons'
import { useEditor, useEditorState } from '@mcut/react'
import { Button } from '@/components/ui/button'
import { Kbd } from '@/components/ui/kbd'
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip'
import { cn } from '@/lib/utils'
import { useEditorUI, type EditorMode } from './editor-ui'
import { ExportDialog } from './export-dialog'
import { MainMenu } from './main-menu'
import { ShortcutsDialog } from './shortcuts-dialog'

function ProjectName({ className }: { className: string }) {
  const engine = useEditor()
  const name = useEditorState((s) => s.project.name)
  return (
    <input
      value={name}
      aria-label="Project name"
      className={cn(
        'rounded-md border border-transparent bg-transparent px-2 py-0.5 text-center text-xs font-medium outline-none hover:border-border focus:border-foreground/20',
        className,
      )}
      onChange={(e) => engine.dispatch({ type: 'updateProject', name: e.target.value || 'Untitled' }, { history: false })}
    />
  )
}

function ThemeToggle() {
  const { theme, setTheme } = useEditorUI()
  return (
    <Tooltip>
      <TooltipTrigger
        render={<Button variant="ghost" size="icon-sm" aria-label="Toggle theme" onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')} />}
      >
        {theme === 'dark' ? <SunIcon /> : <MoonIcon />}
      </TooltipTrigger>
      <TooltipContent>{theme === 'dark' ? 'Light theme' : 'Dark theme'}</TooltipContent>
    </Tooltip>
  )
}

const MODES: Array<{ id: EditorMode; label: string }> = [
  { id: 'edit', label: 'Edit' },
  { id: 'multicam', label: 'Multicam' },
  { id: 'collage', label: 'Collage' },
]

function ModeSwitch() {
  const { mode, setMode } = useEditorUI()
  return (
    <div className="flex items-center gap-0.5 rounded-lg bg-foreground/5 p-0.5">
      {MODES.map(({ id, label }) => (
        <button
          key={id}
          type="button"
          className={cn(
            'rounded-md px-2 py-0.5 text-xs font-medium transition-colors',
            mode === id ? 'bg-card text-foreground shadow-xs' : 'text-muted-foreground hover:text-foreground',
          )}
          onClick={() => setMode(id)}
        >
          {label}
        </button>
      ))}
    </div>
  )
}

function History() {
  const engine = useEditor()
  const canUndo = useEditorState((s) => s.canUndo)
  const canRedo = useEditorState((s) => s.canRedo)
  return (
    <>
      <Tooltip>
        <TooltipTrigger render={<Button variant="ghost" size="icon-sm" disabled={!canUndo} onClick={() => engine.undo()} aria-label="Undo" />}>
          <Undo2Icon />
        </TooltipTrigger>
        <TooltipContent>
          Undo <Kbd>⌘Z</Kbd>
        </TooltipContent>
      </Tooltip>
      <Tooltip>
        <TooltipTrigger render={<Button variant="ghost" size="icon-sm" disabled={!canRedo} onClick={() => engine.redo()} aria-label="Redo" />}>
          <Redo2Icon />
        </TooltipTrigger>
        <TooltipContent>
          Redo <Kbd>⇧⌘Z</Kbd>
        </TooltipContent>
      </Tooltip>
    </>
  )
}

function Toolbar({ children }: { children: ReactNode }) {
  return (
    <div data-slot="editor-toolbar" className="flex h-10 shrink-0 items-center gap-2 px-2 [-webkit-app-region:drag]">
      <MainMenu />
      <History />
      {children}
    </div>
  )
}

export function EditorToolbar() {
  const { layout } = useEditorUI()
  switch (layout) {
    case 'full':
      return (
        <Toolbar>
          <div className="flex flex-1 items-center justify-center gap-2">
            <ProjectName className="w-48" />
            <ModeSwitch />
          </div>
          <span className="hidden items-center gap-1 text-2xs text-muted-foreground lg:flex">
            <Kbd>⌘K</Kbd> commands
          </span>
          <ThemeToggle />
          <ShortcutsDialog />
          <ExportDialog />
        </Toolbar>
      )
    case 'compact':
      return (
        <Toolbar>
          <ProjectName className="min-w-0 flex-1" />
          <ThemeToggle />
          <ExportDialog />
        </Toolbar>
      )
    default: {
      const exhaustive: never = layout
      return exhaustive
    }
  }
}

import { cn } from '@/lib/utils'

export function BrandMark({ className, wordmark = false }: { className?: string; wordmark?: boolean }) {
  return (
    <span
      aria-label="mcut"
      className={cn('inline-flex select-none items-center text-3xl font-bold leading-none italic', className)}
      style={{
        fontFamily: "var(--font-logo), 'Instrument Serif', Georgia, serif",
      }}
    >
      {wordmark ? 'mcut' : 'm'}
    </span>
  )
}

'use client'

import { useState } from 'react'
import {
  CameraIcon,
  CheckIcon,
  ChevronFirstIcon,
  ChevronLastIcon,
  EyeIcon,
  MagnetIcon,
  MaximizeIcon,
  PauseIcon,
  PlayIcon,
  RatioIcon,
  StepBackIcon,
  StepForwardIcon,
  Volume2Icon,
  VolumeXIcon,
} from '@/lib/icons'
import { toast } from 'sonner'
import { useEditorContext, useEditorState, usePlayback, type PreviewQuality } from '@mcut/react'
import { getProjectDurationMs } from '@mcut/timeline'
import { Button } from '@/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { Kbd } from '@/components/ui/kbd'
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip'
import { cn } from '@/lib/utils'
import { useEditorUI, type TimelineEditMode, type TimelineTool } from './editor-ui'
import { formatTimecode } from './format'
import { captureViewportStill } from './viewport-capture'

const TIMELINE_TOOLS: Array<{ id: TimelineTool; label: string; hint: string; key: string }> = [
  { id: 'select', label: 'Select', hint: 'move / trim', key: 'V' },
  { id: 'ripple', label: 'Ripple', hint: 'trim + close gaps', key: 'B' },
  { id: 'roll', label: 'Roll', hint: 'move the cut', key: 'R' },
  { id: 'slip', label: 'Slip', hint: 'shift source in place', key: 'Y' },
  { id: 'slide', label: 'Slide', hint: 'move between neighbors', key: 'U' },
]

const EDIT_MODES: Array<{ id: TimelineEditMode; label: string; hint: string }> = [
  { id: 'normal', label: 'Normal', hint: 'drops never collide' },
  { id: 'overwrite', label: 'Overwrite', hint: 'drops clear their landing range' },
  { id: 'insert', label: 'Insert', hint: 'drops ripple everything right' },
]

const ASPECT_PRESETS = [
  { label: 'Landscape', ratio: '16:9', width: 1920, height: 1080 },
  { label: 'Portrait', ratio: '9:16', width: 1080, height: 1920 },
  { label: 'Square', ratio: '1:1', width: 1080, height: 1080 },
  { label: 'Social', ratio: '4:5', width: 1080, height: 1350 },
  { label: 'Cinema', ratio: '21:9', width: 2560, height: 1080 },
]

const QUALITY_PRESETS: Array<{ label: string; hint: string; value: PreviewQuality }> = [
  { label: 'Auto', hint: 'fit preview', value: 'auto' },
  { label: '720p', hint: 'performance', value: 720 },
  { label: '1080p', hint: 'balanced', value: 1080 },
  { label: 'Full', hint: 'project size', value: 'full' },
]

const CAPTURE_PRESETS = [
  { label: 'Project resolution', hint: '1x', scale: 1 },
  { label: 'High resolution', hint: '2x', scale: 2 },
  { label: 'Ultra high resolution', hint: '4x', scale: 4 },
]

function IconButton({
  label,
  shortcut,
  onClick,
  active,
  children,
  disabled,
  className,
}: {
  label: string
  shortcut?: string
  onClick: () => void
  active?: boolean
  disabled?: boolean
  children: React.ReactNode
  className?: string
}) {
  return (
    <Tooltip>
      <TooltipTrigger
        render={
          <Button
            variant={active ? 'secondary' : 'ghost'}
            size="icon-sm"
            className={cn(active === undefined ? undefined : 'transition-none', className)}
            onClick={onClick}
            disabled={disabled}
            aria-label={label}
          />
        }
      >
        {children}
      </TooltipTrigger>
      <TooltipContent className="flex items-center gap-1.5">
        {label}
        {shortcut && <Kbd>{shortcut}</Kbd>}
      </TooltipContent>
    </Tooltip>
  )
}

function Timecode() {
  const currentTimeMs = usePlayback((s) => s.currentTimeMs)
  const durationMs = useEditorState((s) => getProjectDurationMs(s.project))
  return (
    <span className="min-w-30 text-center font-mono text-xs tabular-nums text-muted-foreground select-none">
      <span className="text-foreground">{formatTimecode(currentTimeMs)}</span>
      <span className="px-0.5 opacity-50">/</span>
      {formatTimecode(durationMs)}
    </span>
  )
}

function CompactTransportBar() {
  const { engine } = useEditorContext()
  const isPlaying = usePlayback((s) => s.isPlaying)
  const muted = usePlayback((s) => s.muted)
  const fps = useEditorState((s) => s.project.fps)
  const frameMs = 1000 / fps
  const seekBy = (deltaMs: number) => engine.seek(engine.playback.state.currentTimeMs + deltaMs)

  return (
    <div className="flex h-12 shrink-0 items-center gap-1 px-2">
      <div className="flex flex-1 items-center justify-center gap-1">
        <IconButton label="Go to start" className="size-10" onClick={() => engine.seek(0)}>
          <ChevronFirstIcon />
        </IconButton>
        <IconButton label="Previous frame" className="size-10" onClick={() => seekBy(-frameMs)}>
          <StepBackIcon />
        </IconButton>
        <IconButton label={isPlaying ? 'Pause' : 'Play'} className="size-10" onClick={() => (isPlaying ? engine.pause() : engine.play())}>
          <span className="flex size-9 items-center justify-center rounded-full bg-primary text-primary-foreground [&_svg]:size-4">
            {isPlaying ? <PauseIcon /> : <PlayIcon className="translate-x-px" />}
          </span>
        </IconButton>
        <IconButton label="Next frame" className="size-10" onClick={() => seekBy(frameMs)}>
          <StepForwardIcon />
        </IconButton>
        <Timecode />
      </div>
      <IconButton label={muted ? 'Unmute' : 'Mute'} className="size-10" onClick={() => engine.setMuted(!muted)}>
        {muted ? <VolumeXIcon className="text-destructive" /> : <Volume2Icon />}
      </IconButton>
    </div>
  )
}

export function TransportBar() {
  const { layout } = useEditorUI()
  switch (layout) {
    case 'full':
      return <FullTransportBar />
    case 'compact':
      return <CompactTransportBar />
    default: {
      const exhaustive: never = layout
      return exhaustive
    }
  }
}

function FullTransportBar() {
  const { engine, pool } = useEditorContext()
  const isPlaying = usePlayback((s) => s.isPlaying)
  const muted = usePlayback((s) => s.muted)
  const fps = useEditorState((s) => s.project.fps)
  const {
    snapEnabled,
    setSnapEnabled,
    timelineTool,
    setTimelineTool,
    editMode,
    setEditMode,
    autoCrossfade,
    setAutoCrossfade,
    previewQuality,
    setPreviewQuality,
  } = useEditorUI()
  const [capturingScale, setCapturingScale] = useState<number | null>(null)
  const frameMs = 1000 / fps

  const seekBy = (deltaMs: number) => engine.seek(engine.playback.state.currentTimeMs + deltaMs)

  const captureStill = async (scale: number) => {
    setCapturingScale(scale)
    try {
      const still = await captureViewportStill(engine, { source: pool, scale })
      toast.success(`Captured ${still.width}×${still.height} still to the media bin`)
    } catch (error) {
      toast.error(error instanceof Error ? error.message : 'Could not capture still')
    } finally {
      setCapturingScale(null)
    }
  }

  return (
    <div className="flex h-11 shrink-0 items-center gap-0.5 px-2">
      <div className="mr-1 flex items-center gap-px rounded-md bg-muted/40 p-0.5">
        {TIMELINE_TOOLS.map((tool) => (
          <Tooltip key={tool.id}>
            <TooltipTrigger
              render={
                <Button
                  variant={timelineTool === tool.id ? 'secondary' : 'ghost'}
                  size="icon-sm"
                  className="size-6 font-mono text-2xs transition-none"
                  onClick={() => setTimelineTool(tool.id)}
                  aria-label={`${tool.label} tool`}
                />
              }
            >
              {tool.key}
            </TooltipTrigger>
            <TooltipContent className="flex items-center gap-1.5">
              {tool.label} — {tool.hint}
              <Kbd>{tool.key}</Kbd>
            </TooltipContent>
          </Tooltip>
        ))}
      </div>
      <IconButton label={snapEnabled ? 'Snapping on' : 'Snapping off'} shortcut="N" active={snapEnabled} onClick={() => setSnapEnabled(!snapEnabled)}>
        <MagnetIcon />
      </IconButton>
      <DropdownMenu>
        <DropdownMenuTrigger
          render={
            <Button
              variant={editMode === 'normal' ? 'ghost' : 'secondary'}
              size="sm"
              className="h-7 px-2 font-mono text-2xs uppercase transition-none"
              aria-label="Edit mode"
              title="Edit mode for drops and inserts"
            />
          }
        >
          {editMode}
        </DropdownMenuTrigger>
        <DropdownMenuContent align="start">
          <DropdownMenuLabel>Edit mode</DropdownMenuLabel>
          <DropdownMenuSeparator />
          {EDIT_MODES.map((mode) => (
            <DropdownMenuItem key={mode.id} onClick={() => setEditMode(mode.id)}>
              {editMode === mode.id ? <CheckIcon className="size-3.5" /> : <span className="size-3.5" />}
              {mode.label}
              <span className="ml-auto pl-3 font-mono text-2xs text-muted-foreground">{mode.hint}</span>
            </DropdownMenuItem>
          ))}
          <DropdownMenuSeparator />
          <DropdownMenuItem onClick={() => setAutoCrossfade(!autoCrossfade)}>
            {autoCrossfade ? <CheckIcon className="size-3.5" /> : <span className="size-3.5" />}
            Auto-crossfade
            <span className="ml-auto pl-3 font-mono text-2xs text-muted-foreground">dissolve on push</span>
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>
      <DropdownMenu>
        <DropdownMenuTrigger render={<Button variant="ghost" size="icon-sm" aria-label="Canvas size" title="Canvas size" />}>
          <RatioIcon />
        </DropdownMenuTrigger>
        <DropdownMenuContent align="start">
          <DropdownMenuLabel>Canvas</DropdownMenuLabel>
          <DropdownMenuSeparator />
          {ASPECT_PRESETS.map((preset) => (
            <DropdownMenuItem
              key={preset.label}
              onClick={() =>
                engine.dispatch({
                  type: 'updateProject',
                  width: preset.width,
                  height: preset.height,
                })
              }
            >
              {preset.label}
              <span className="ml-auto pl-4 font-mono text-2xs text-muted-foreground tabular-nums">
                {preset.ratio} · {preset.width}×{preset.height}
              </span>
            </DropdownMenuItem>
          ))}
        </DropdownMenuContent>
      </DropdownMenu>
      <DropdownMenu>
        <DropdownMenuTrigger render={<Button variant="ghost" size="icon-sm" aria-label="Preview quality" title="Preview quality" />}>
          <EyeIcon />
        </DropdownMenuTrigger>
        <DropdownMenuContent align="start">
          <DropdownMenuLabel>Preview quality</DropdownMenuLabel>
          <DropdownMenuSeparator />
          {QUALITY_PRESETS.map((preset) => (
            <DropdownMenuItem key={preset.label} onClick={() => setPreviewQuality(preset.value)}>
              {previewQuality === preset.value ? <CheckIcon className="size-3.5" /> : <span className="size-3.5" />}
              {preset.label}
              <span className="ml-auto pl-3 font-mono text-2xs text-muted-foreground">{preset.hint}</span>
            </DropdownMenuItem>
          ))}
        </DropdownMenuContent>
      </DropdownMenu>

      <div className="flex flex-1 items-center justify-center gap-0.5">
        <IconButton label="Go to start" onClick={() => engine.seek(0)}>
          <ChevronFirstIcon />
        </IconButton>
        <IconButton label="Previous frame" shortcut="←" onClick={() => seekBy(-frameMs)}>
          <StepBackIcon />
        </IconButton>
        <IconButton label={isPlaying ? 'Pause' : 'Play'} shortcut="Space" onClick={() => (isPlaying ? engine.pause() : engine.play())}>
          <span className="flex size-7 items-center justify-center rounded-full bg-primary text-primary-foreground [&_svg]:size-3.5">
            {isPlaying ? <PauseIcon /> : <PlayIcon className="translate-x-px" />}
          </span>
        </IconButton>
        <IconButton label="Next frame" shortcut="→" onClick={() => seekBy(frameMs)}>
          <StepForwardIcon />
        </IconButton>
        <IconButton label="Go to end" onClick={() => engine.seek(getProjectDurationMs(engine.project))}>
          <ChevronLastIcon />
        </IconButton>
        <Timecode />
      </div>

      <IconButton label={muted ? 'Unmute' : 'Mute'} onClick={() => engine.setMuted(!muted)}>
        {muted ? <VolumeXIcon className="text-destructive" /> : <Volume2Icon />}
      </IconButton>
      <DropdownMenu>
        <DropdownMenuTrigger
          render={<Button variant="ghost" size="icon-sm" aria-label="Capture still" title="Capture still" disabled={capturingScale !== null} />}
        >
          <CameraIcon />
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end">
          <DropdownMenuLabel>Capture still</DropdownMenuLabel>
          <DropdownMenuSeparator />
          {CAPTURE_PRESETS.map((preset) => (
            <DropdownMenuItem key={preset.scale} disabled={capturingScale !== null} onClick={() => void captureStill(preset.scale)}>
              {preset.label}
              <span className="ml-auto pl-3 font-mono text-2xs text-muted-foreground">{capturingScale === preset.scale ? 'saving' : preset.hint}</span>
            </DropdownMenuItem>
          ))}
        </DropdownMenuContent>
      </DropdownMenu>
      <IconButton
        label="Fullscreen preview"
        onClick={() => {
          document
            .querySelector('[data-mcut-player]')
            ?.requestFullscreen?.()
            .catch(() => {})
        }}
      >
        <MaximizeIcon />
      </IconButton>
    </div>
  )
}

'use client'

import { renderFrame, type FrameSource } from '@mcut/compositor'
import { createAsset, getActiveMediaItems, type PreviewMediaPool } from '@mcut/media'
import type { AssetRef, EditorEngine } from '@mcut/timeline'
import { ensureProjectFontsLoaded } from './font-library'
import { saveAssetBlob } from './persistence'

export interface ViewportStill {
  asset: AssetRef
  file: File
  width: number
  height: number
}

export interface CaptureViewportStillOptions {
  scale?: number
  source?: FrameSource | PreviewMediaPool
}

function slugPart(value: string): string {
  return (
    value
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '') || 'mcut'
  )
}

function timePart(timeMs: number): string {
  const totalSeconds = Math.max(0, Math.floor(timeMs / 1000))
  const ms = Math.max(0, Math.round(timeMs % 1000))
  const seconds = totalSeconds % 60
  const minutes = Math.floor(totalSeconds / 60) % 60
  const hours = Math.floor(totalSeconds / 3600)
  return `${hours.toString().padStart(2, '0')}-${minutes.toString().padStart(2, '0')}-${seconds.toString().padStart(2, '0')}-${ms.toString().padStart(3, '0')}`
}

async function canvasToPngFile(canvas: HTMLCanvasElement, filename: string): Promise<File> {
  const blob = await new Promise<Blob | null>((resolve) => canvas.toBlob(resolve, 'image/png'))
  if (!blob) throw new Error('Could not encode PNG')
  return new File([blob], filename, { type: 'image/png' })
}

export async function captureViewportStill(engine: EditorEngine, options: CaptureViewportStillOptions = {}): Promise<ViewportStill> {
  const project = engine.project
  const timeMs = engine.playback.state.currentTimeMs
  const scale = Math.max(1, Math.min(4, Math.round(options.scale ?? 1)))
  const width = Math.max(1, Math.round(project.width * scale))
  const height = Math.max(1, Math.round(project.height * scale))
  const canvas = document.createElement('canvas')
  canvas.width = width
  canvas.height = height
  const ctx = canvas.getContext('2d')
  if (!ctx) throw new Error('Could not create capture canvas')

  const source = options.source
  if (source && 'sync' in source) {
    source.sync(getActiveMediaItems(project, timeMs), {
      isPlaying: false,
      playbackRate: engine.playback.state.playbackRate,
      masterVolume: engine.playback.state.volume,
      muted: true,
    })
  }

  await ensureProjectFontsLoaded(project)
  ctx.setTransform(scale, 0, 0, scale, 0, 0)
  renderFrame(ctx, project, timeMs, { source })

  const suffix = scale === 1 ? '' : `-${scale}x`
  const file = await canvasToPngFile(canvas, `${slugPart(project.name)}-${timePart(timeMs)}${suffix}.png`)
  const asset = await createAsset({ kind: 'blob', blob: file, name: file.name })
  engine.dispatch({ type: 'addAsset', asset }, { history: false })
  await saveAssetBlob(asset, file)
  return { asset, file, width, height }
}

'use client'

import { ChevronRightIcon, XIcon } from '@/lib/icons'
import { useEditor, usePlayback } from '@mcut/react'
import { getKeyframes, getStaticValue, hasKeyframes, isOnKeyframe, type AnimatableProperty, type Easing, type TimelineElement } from '@mcut/timeline'
import { cn } from '@/lib/utils'
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuLabel, DropdownMenuTrigger } from '@/components/ui/dropdown-menu'
import { useEditorUI } from './editor-ui'

export const EASING_PRESETS: Array<{ label: string; value: Easing }> = [
  { label: 'Linear', value: 'linear' },
  { label: 'Ease in', value: 'easeIn' },
  { label: 'Ease out', value: 'easeOut' },
  { label: 'Ease in-out', value: 'easeInOut' },
  { label: 'Hold', value: 'hold' },
]

export function localPlayheadMs(element: TimelineElement, timelineMs: number): number {
  return Math.max(0, Math.min(element.durationMs, Math.round(timelineMs - element.startMs)))
}

function restsAtZeroWithNoStaticCounterpart(property: AnimatableProperty): property is 'blur' {
  return property === 'blur'
}

export function Diamond({ filled, armed, className }: { filled: boolean; armed?: boolean; className?: string }) {
  return (
    <span
      className={cn(
        'inline-block size-2 rotate-45 border transition-colors',
        filled ? 'border-primary bg-primary' : armed ? 'border-primary bg-transparent' : 'border-muted-foreground/70 bg-transparent',
        className,
      )}
    />
  )
}

export function KeyframeRowControls({ element, property }: { element: TimelineElement; property: AnimatableProperty }) {
  const engine = useEditor()
  const { setCurveEditorTarget } = useEditorUI()
  const armed = hasKeyframes(element, property)
  const playheadMs = usePlayback((s) => Math.round(s.currentTimeMs))
  const localMs = localPlayheadMs(element, playheadMs)
  const track = getKeyframes(element, property)
  const onKeyframe = armed && isOnKeyframe(element, property, playheadMs)
  const previous = [...track].reverse().find((k) => k.timeMs < localMs)
  const next = track.find((k) => k.timeMs > localMs)
  const currentKeyframe = track.find((k) => Math.abs(k.timeMs - localMs) <= 1)

  const toggle = () => {
    try {
      if (onKeyframe) {
        if (track.length === 1) {
          const value = currentKeyframe?.value
          engine.transact(() => {
            engine.dispatch({ type: 'clearKeyframes', elementId: element.id, property })
            if (value !== undefined) applyStatic(value)
          })
        } else {
          engine.dispatch({
            type: 'removeKeyframe',
            elementId: element.id,
            property,
            timeMs: currentKeyframe!.timeMs,
          })
        }
      } else {
        const value = armed ? undefined : getStaticValue(element, property)
        engine.dispatch({
          type: 'setKeyframe',
          elementId: element.id,
          property,
          timeMs: localMs,
          value: value ?? interpolatedNow(),
        })
      }
    } catch {}
  }

  const interpolatedNow = () => {
    const before = [...track].reverse().find((k) => k.timeMs <= localMs)
    const after = track.find((k) => k.timeMs >= localMs)
    if (!before) return after!.value
    if (!after || after === before) return before.value
    const t = (localMs - before.timeMs) / (after.timeMs - before.timeMs)
    return before.value + (after.value - before.value) * t
  }

  const applyStatic = (value: number) => {
    if (restsAtZeroWithNoStaticCounterpart(property)) return
    const patch: Record<string, unknown> = {}
    if (property === 'opacity') patch.opacity = Math.min(1, Math.max(0, value))
    else if (property === 'volume') patch.volume = Math.min(2, Math.max(0, value))
    else if (property === 'letterSpacing') {
      if (element.type !== 'text') return
      patch.style = { ...element.style, letterSpacing: value }
    } else if ('transform' in element) {
      const key = { 'position.x': 'x', 'position.y': 'y', 'scale.x': 'scaleX', 'scale.y': 'scaleY', rotation: 'rotation' }[property]
      patch.transform = { ...element.transform, [key as string]: value }
    }
    engine.dispatch({ type: 'updateElement', elementId: element.id, patch })
  }

  const seekTo = (timeMs: number) => engine.seek(element.startMs + timeMs)

  const disarm = () => {
    if (!window.confirm(`Delete all ${track.length} ${property} keyframe(s)?`)) return
    engine.dispatch({ type: 'clearKeyframes', elementId: element.id, property })
  }

  return (
    <span className="group/kf flex shrink-0 items-center gap-px">
      <button
        type="button"
        className="flex size-4 items-center justify-center text-muted-foreground hover:text-foreground disabled:opacity-25"
        disabled={!previous}
        title="Previous keyframe"
        onClick={() => previous && seekTo(previous.timeMs)}
      >
        <ChevronRightIcon className="size-3 rotate-180" />
      </button>
      <button
        type="button"
        className="flex size-4 items-center justify-center"
        title={onKeyframe ? 'Remove keyframe at playhead' : armed ? 'Add keyframe at playhead' : 'Arm keyframes (stopwatch on) — adds one at the playhead'}
        onClick={toggle}
      >
        <Diamond filled={onKeyframe} armed={armed} />
      </button>
      <button
        type="button"
        className="flex size-4 items-center justify-center text-muted-foreground hover:text-foreground disabled:opacity-25"
        disabled={!next}
        title="Next keyframe"
        onClick={() => next && seekTo(next.timeMs)}
      >
        <ChevronRightIcon className="size-3" />
      </button>
      {armed && onKeyframe && currentKeyframe && (
        <DropdownMenu>
          <DropdownMenuTrigger
            render={
              <button
                type="button"
                className="flex h-4 items-center px-0.5 font-mono text-2xs text-muted-foreground hover:text-foreground"
                title="Interpolation toward the next keyframe"
              />
            }
          >
            ∿
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            <DropdownMenuLabel>Interpolation</DropdownMenuLabel>
            <DropdownMenuItem onClick={() => setCurveEditorTarget({ elementId: element.id, property })}>
              Curve editor…
              <span className="ml-auto pl-3 font-mono text-2xs text-muted-foreground">∿</span>
            </DropdownMenuItem>
            {EASING_PRESETS.map((preset) => (
              <DropdownMenuItem
                key={preset.label}
                onClick={() =>
                  engine.dispatch({
                    type: 'setKeyframeEasing',
                    elementId: element.id,
                    property,
                    timeMs: currentKeyframe.timeMs,
                    easing: preset.value,
                  })
                }
              >
                {preset.label}
                {(currentKeyframe.easing ?? 'linear') === preset.value && <span className="ml-auto pl-3 text-primary">•</span>}
              </DropdownMenuItem>
            ))}
          </DropdownMenuContent>
        </DropdownMenu>
      )}
      {armed && (
        <button
          type="button"
          className="flex size-4 items-center justify-center text-muted-foreground opacity-0 transition-opacity group-hover/kf:opacity-100 hover:text-destructive"
          title="Stopwatch off — delete all keyframes for this property"
          onClick={disarm}
        >
          <XIcon className="size-2.5" />
        </button>
      )}
    </span>
  )
}

'use client'

import { useMemo, useRef, useState, type PointerEvent as ReactPointerEvent } from 'react'
import { useEditor } from '@mcut/react'
import {
  animatableProperties,
  getEffectiveVolume,
  getKeyframes,
  hasKeyframes,
  type AnimatableProperty,
  type Project,
  type TimelineElement,
} from '@mcut/timeline'
import { cn } from '@/lib/utils'
import { useEditorUI, useRerenderOnProjectEdits } from './editor-ui'
import { formatTimecode } from './format'
import { collectSnapTargets, snapTime, type SnapTarget } from './timeline-snap'

const SNAP_PX = 8
export const KEYFRAME_DRAG_THRESHOLD_PX = 3

function aggregatedTimes(element: TimelineElement): number[] {
  const times = new Set<number>()
  for (const property of animatableProperties(element)) {
    for (const keyframe of getKeyframes(element, property)) times.add(keyframe.timeMs)
  }
  return [...times].sort((a, b) => a - b)
}

export function keyframePropertiesAt(element: TimelineElement, timeMs: number): AnimatableProperty[] {
  return animatableProperties(element).filter((property) => getKeyframes(element, property).some((keyframe) => keyframe.timeMs === timeMs))
}

export function isKeyframeDragPastThreshold(startClientX: number, clientX: number): boolean {
  return Math.abs(clientX - startClientX) >= KEYFRAME_DRAG_THRESHOLD_PX
}

export function isKeyframeSnapEnabled(snapEnabled: boolean, altKey: boolean): boolean {
  return snapEnabled && !altKey
}

export function resolveKeyframeClickGesture({
  moved,
  startedAltKey,
  endedAltKey,
}: {
  moved: boolean
  startedAltKey: boolean
  endedAltKey: boolean
}): 'delete' | 'seek' | 'none' {
  if (moved) return 'none'
  return startedAltKey || endedAltKey ? 'delete' : 'seek'
}

export function clampKeyframeDragTarget(
  element: TimelineElement,
  properties: readonly AnimatableProperty[],
  originTimeMs: number,
  desiredTimeMs: number,
): number {
  let min = 0
  let max = element.durationMs
  for (const property of properties) {
    const track = getKeyframes(element, property)
    const previous = [...track].reverse().find((keyframe) => keyframe.timeMs < originTimeMs)
    const next = track.find((keyframe) => keyframe.timeMs > originTimeMs)
    if (previous) min = Math.max(min, previous.timeMs + 1)
    if (next) max = Math.min(max, next.timeMs - 1)
  }
  if (min > max) return originTimeMs
  return Math.max(min, Math.min(max, Math.round(desiredTimeMs)))
}

export function canMoveKeyframeGroup(element: TimelineElement, properties: readonly AnimatableProperty[], fromTimeMs: number, toTimeMs: number): boolean {
  return properties.every((property) => {
    const track = getKeyframes(element, property)
    return track.some((keyframe) => keyframe.timeMs === fromTimeMs) && (toTimeMs === fromTimeMs || !track.some((keyframe) => keyframe.timeMs === toTimeMs))
  })
}

function keyframeSnapTargets(project: Project, playheadMs: number, element: TimelineElement): SnapTarget[] {
  const selectedClipEdges: SnapTarget[] = [
    { timeMs: element.startMs, kind: 'clip-start' },
    { timeMs: element.startMs + element.durationMs, kind: 'clip-end' },
  ]
  return [...collectSnapTargets(project, playheadMs, new Set([element.id])), ...selectedClipEdges].sort((a, b) => a.timeMs - b.timeMs)
}

function keyframeMarkerRows(element: TimelineElement): Array<{ timeMs: number; key: string }> {
  const signatureCounts = new Map<string, number>()
  return aggregatedTimes(element).map((timeMs) => {
    const signature = keyframePropertiesAt(element, timeMs).join('|')
    const ordinal = signatureCounts.get(signature) ?? 0
    signatureCounts.set(signature, ordinal + 1)
    return { timeMs, key: `keyframe-${signature}-${ordinal}` }
  })
}

export function KeyframeMarkers({ element, pxPerMs }: { element: TimelineElement; pxPerMs: number }) {
  const engine = useEditor()
  useRerenderOnProjectEdits()
  const { snapEnabled, setSnapGuideMs } = useEditorUI()
  const dragRef = useRef<{
    originTimeMs: number
    currentTimeMs: number
    startClientX: number
    startedAltKey: boolean
    moved: boolean
    transactionStarted: boolean
    properties: AnimatableProperty[]
  } | null>(null)
  const [dragBadge, setDragBadge] = useState<{
    timeMs: number
    noSnap: boolean
  } | null>(null)

  const removeAt = (timeMs: number) => {
    engine.transact(() => {
      for (const property of animatableProperties(element)) {
        if (getKeyframes(element, property).some((k) => k.timeMs === timeMs)) {
          try {
            engine.dispatch({ type: 'removeKeyframe', elementId: element.id, property, timeMs })
          } catch {}
        }
      }
    })
  }

  const onPointerDown = (timeMs: number) => (event: ReactPointerEvent<HTMLButtonElement>) => {
    event.stopPropagation()
    const properties = keyframePropertiesAt(element, timeMs)
    if (properties.length === 0) return
    dragRef.current = {
      originTimeMs: timeMs,
      currentTimeMs: timeMs,
      startClientX: event.clientX,
      startedAltKey: event.altKey,
      moved: false,
      transactionStarted: false,
      properties,
    }
    event.currentTarget.setPointerCapture(event.pointerId)
  }

  const onPointerMove = (event: ReactPointerEvent<HTMLButtonElement>) => {
    const drag = dragRef.current
    if (!drag) return
    const deltaPx = event.clientX - drag.startClientX
    if (!drag.moved && !isKeyframeDragPastThreshold(drag.startClientX, event.clientX)) return
    if (!drag.transactionStarted) {
      drag.transactionStarted = true
      engine.beginTransaction()
    }
    drag.moved = true

    const desiredLocal = drag.originTimeMs + deltaPx / pxPerMs
    const live = engine.project.tracks.flatMap((t) => t.elements).find((e) => e.id === element.id)
    if (!live) return
    const snapping = isKeyframeSnapEnabled(snapEnabled, event.altKey)
    const clampedDesired = clampKeyframeDragTarget(live, drag.properties, drag.originTimeMs, desiredLocal)
    const snapped = snapTime(
      element.startMs + clampedDesired,
      keyframeSnapTargets(engine.project, engine.playback.state.currentTimeMs, element),
      SNAP_PX / pxPerMs,
      { enabled: snapping },
    )
    const toTimeMs = clampKeyframeDragTarget(live, drag.properties, drag.originTimeMs, snapped.ms - element.startMs)

    setSnapGuideMs(snapping ? snapped.guideMs : null)
    setDragBadge({ timeMs: toTimeMs, noSnap: event.altKey })
    if (toTimeMs === drag.currentTimeMs) return
    if (!canMoveKeyframeGroup(live, drag.properties, drag.currentTimeMs, toTimeMs)) return

    for (const property of drag.properties) {
      try {
        engine.dispatch({
          type: 'moveKeyframe',
          elementId: element.id,
          property,
          fromTimeMs: drag.currentTimeMs,
          toTimeMs,
        })
      } catch {
        return
      }
    }
    drag.currentTimeMs = toTimeMs
  }

  const finishPointer = (event: ReactPointerEvent<HTMLButtonElement>, cancelled = false) => {
    const drag = dragRef.current
    if (!drag) return
    dragRef.current = null
    if (drag.transactionStarted) engine.endTransaction()
    setSnapGuideMs(null)
    setDragBadge(null)
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId)
    }
    if (cancelled) return

    const gesture = resolveKeyframeClickGesture({
      moved: drag.moved,
      startedAltKey: drag.startedAltKey,
      endedAltKey: event.altKey,
    })
    if (gesture === 'delete') removeAt(drag.originTimeMs)
    if (gesture === 'seek') engine.seek(element.startMs + drag.originTimeMs)
  }

  return (
    <>
      {keyframeMarkerRows(element).map(({ timeMs, key }) => (
        <button
          key={key}
          type="button"
          className="absolute bottom-0 z-30 flex h-3.5 w-3 -translate-x-1/2 cursor-ew-resize items-center justify-center"
          style={{ left: timeMs * pxPerMs }}
          title="Keyframe - drag to retime, Option-drag no snap, Option-click delete"
          onPointerDown={onPointerDown(timeMs)}
          onPointerMove={onPointerMove}
          onPointerUp={(event) => finishPointer(event)}
          onPointerCancel={(event) => finishPointer(event, true)}
        >
          <span className="size-1.5 rotate-45 border border-overlay/60 bg-overlay-foreground shadow-sm" />
        </button>
      ))}
      {dragBadge && (
        <span
          className="pointer-events-none absolute bottom-4 z-40 flex -translate-x-1/2 items-center gap-1 rounded-sm bg-overlay/80 px-1.5 py-0.5 font-mono text-2xs text-overlay-foreground shadow-sm"
          style={{ left: dragBadge.timeMs * pxPerMs }}
        >
          {formatTimecode(element.startMs + dragBadge.timeMs)}
          {dragBadge.noSnap && <span className="font-sans text-2xs uppercase">No snap</span>}
        </span>
      )}
    </>
  )
}

export function VolumeBand({
  element,
  widthPx,
  heightPx,
  interactive,
}: {
  element: TimelineElement & { type: 'audio' | 'video' }
  widthPx: number
  heightPx: number
  interactive: boolean
}) {
  const engine = useEditor()
  const dragRef = useRef<{ targetTimeMs: number | null } | null>(null)
  const armed = hasKeyframes(element, 'volume')

  const width = Math.max(1, Math.round(widthPx))
  const height = Math.max(1, Math.round(heightPx))
  const points = useMemo(() => {
    const coords: string[] = []
    for (let x = 0; x <= width; x += 3) {
      const timelineMs = element.startMs + (x / width) * element.durationMs
      const volume = Math.max(0, Math.min(2, getEffectiveVolume(element, timelineMs)))
      const y = Math.round((height - (volume / 2) * height) * 10) / 10
      coords.push(`${x},${y}`)
    }
    return coords.join(' ')
  }, [element, width, height])

  const valueFromY = (event: ReactPointerEvent<HTMLDivElement>): number => {
    const rect = event.currentTarget.getBoundingClientRect()
    const ratio = 1 - (event.clientY - rect.top) / rect.height
    return Math.round(Math.max(0, Math.min(2, ratio * 2)) * 100) / 100
  }

  const localTimeFromX = (event: ReactPointerEvent<HTMLDivElement>): number => {
    const rect = event.currentTarget.getBoundingClientRect()
    const ratio = (event.clientX - rect.left) / rect.width
    return Math.max(0, Math.min(element.durationMs, Math.round(ratio * element.durationMs)))
  }

  const dragTarget = (event: ReactPointerEvent<HTMLDivElement>): number | null => {
    if (event.metaKey || event.ctrlKey) {
      const timeMs = localTimeFromX(event)
      try {
        engine.dispatch({
          type: 'setKeyframe',
          elementId: element.id,
          property: 'volume',
          timeMs,
          value: valueFromY(event),
        })
      } catch {}
      return timeMs
    }
    if (armed) {
      const timeMs = localTimeFromX(event)
      const track = getKeyframes(element, 'volume')
      const nearest = track.reduce((best, k) => (Math.abs(k.timeMs - timeMs) < Math.abs(best.timeMs - timeMs) ? k : best))
      return nearest.timeMs
    }
    return null
  }

  const onPointerDown = (event: ReactPointerEvent<HTMLDivElement>) => {
    if (!interactive) return
    event.stopPropagation()
    engine.beginTransaction()
    dragRef.current = { targetTimeMs: dragTarget(event) }
    event.currentTarget.setPointerCapture(event.pointerId)
  }

  const onPointerMove = (event: ReactPointerEvent<HTMLDivElement>) => {
    const drag = dragRef.current
    if (!drag) return
    const value = valueFromY(event)
    try {
      if (drag.targetTimeMs === null) {
        engine.dispatch({ type: 'updateElement', elementId: element.id, patch: { volume: value } })
      } else {
        engine.dispatch({
          type: 'setKeyframe',
          elementId: element.id,
          property: 'volume',
          timeMs: drag.targetTimeMs,
          value,
        })
      }
    } catch {}
  }

  const onPointerUp = (event: ReactPointerEvent<HTMLDivElement>) => {
    if (!dragRef.current) return
    dragRef.current = null
    engine.endTransaction()
    event.currentTarget.releasePointerCapture(event.pointerId)
  }

  return (
    <div
      className={cn('absolute inset-0 z-20', interactive ? 'cursor-ns-resize' : 'pointer-events-none')}
      title={interactive ? 'Volume band — drag to set, ⌘-click to add a keyframe' : undefined}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onPointerCancel={onPointerUp}
    >
      <svg className="pointer-events-none absolute inset-0 size-full" viewBox={`0 0 ${width} ${height}`} preserveAspectRatio="none" aria-hidden="true">
        <polyline points={points} fill="none" stroke="rgba(103, 232, 249, 0.95)" strokeWidth={1.5} vectorEffect="non-scaling-stroke" />
      </svg>
    </div>
  )
}

