import type { AnimationPreset, EditorEngine, TimelineElement, ZoomPreset } from '@mcut/timeline'

const PUNCH_ZOOM_DURATION_MS = 240
const PUNCH_ZOOM_SCALE = 1.15

const PUNCH_ZOOM_PRESET: ZoomPreset = {
  name: 'Punch zoom',
  durationMs: PUNCH_ZOOM_DURATION_MS,
  tracks: {
    'scale.x': [
      { t: 0, value: 1, easing: { cubicBezier: [0.16, 1, 0.3, 1] } },
      { t: 1, value: PUNCH_ZOOM_SCALE },
    ],
    'scale.y': [
      { t: 0, value: 1, easing: { cubicBezier: [0.16, 1, 0.3, 1] } },
      { t: 1, value: PUNCH_ZOOM_SCALE },
    ],
  },
}

export function applyStudioAnimationPreset(engine: EditorEngine, element: TimelineElement, preset: AnimationPreset, timelineMs: number = element.startMs) {
  if (preset !== 'punch-zoom') {
    engine.dispatch({ type: 'applyAnimationPreset', elementId: element.id, preset })
    return
  }

  const atMs = Math.round(Math.max(0, Math.min(timelineMs - element.startMs, element.durationMs - PUNCH_ZOOM_DURATION_MS)))
  engine.dispatch({
    type: 'applyZoomPreset',
    elementId: element.id,
    preset: PUNCH_ZOOM_PRESET,
    atMs,
  })
}

import { ZOOM_PRESETS, type ZoomPreset } from '@mcut/timeline'

function punchOutPreset(preset: ZoomPreset): ZoomPreset {
  if (preset.name !== 'Punch out') return preset

  return {
    ...preset,
    tracks: {
      ...preset.tracks,
      'scale.x': [
        { t: 0, value: 1, easing: preset.tracks['scale.x']?.[0]?.easing },
        { t: 1, value: 0.8 },
      ],
      'scale.y': [
        { t: 0, value: 1, easing: preset.tracks['scale.y']?.[0]?.easing },
        { t: 1, value: 0.8 },
      ],
    },
  }
}

export const STUDIO_ZOOM_PRESETS: ZoomPreset[] = ZOOM_PRESETS.map(punchOutPreset)

