  const apply = (values: Record<string, unknown>) => {
    try {
      onApply(values)
      setOpen(false)
    } catch (error) {
      toast.error(error instanceof Error ? error.message : 'Could not apply the preset')
    }
  }

  return (
    <>
      <NameDialog draft={draft} title="Save the current settings as a preset" onSubmit={save} onCancel={() => setDraft(null)} />
      <Popover open={open} onOpenChange={setOpen}>
        <PopoverTrigger render={<Button variant="ghost" size="icon-xs" className={cn('size-5 text-muted-foreground', className)} title="Presets" />}>
          <SwatchIcon />
        </PopoverTrigger>
        <PopoverContent className="w-56 p-1" align="end">
          {presets.length === 0 && (
            <p className="px-2 py-1.5 text-2xs text-muted-foreground">No presets yet — save the current settings to reuse them on any matching section.</p>
