type AudioActivityPayload = z.infer<typeof MCP_TOOL_INPUTS.get_audio_activity>

interface AudioActivitySource {
  asset: AssetRef
  element: VideoElement | AudioElement
  track: Track
}

interface SourceRange {
  startMs: number
  endMs: number
  durationMs: number
}

type AudioActivityAnalyzer = (src: string, options?: AudioActivityOptions) => Promise<AudioActivity | null>

const DEFAULT_BRIDGE_PORT = '44737'
const BRIDGE_CONFIG_STORAGE_KEY = 'mcut.liveMcpBridge'

export const LIVE_MCP_STATIC_TOOL_REQUESTS = MCP_AGENT_TOOL_NAMES

export const LIVE_MCP_DYNAMIC_TOOL_REQUESTS = ['dispatch_command'] as const

export const LIVE_MCP_REQUEST_TYPES = [...LIVE_MCP_STATIC_TOOL_REQUESTS, ...LIVE_MCP_DYNAMIC_TOOL_REQUESTS] as const

export function liveMcpOperatorToolName(operatorId: OperatorId): string {
  return operatorToolName(operatorId)
}

function searchProjectTranscript(project: Project, query: string): unknown {
  const captionRefs = getProjectCaptions(project)
  const captions = captionRefs.map((ref) => ref.caption)
  const byId = new Map<string, (typeof captionRefs)[number]>(captionRefs.map((ref) => [ref.caption.id, ref]))
  const matches = searchCaptions(captions, query).map((match) => {
    const ref = byId.get(match.captionId)
    const text = ref?.caption.text ?? ''
    return {
      ...match,
      text: text.slice(match.startChar, match.endChar),
      captionText: text,
      trackId: ref?.trackId,
      trackName: ref?.trackName,
      startMs: match.timeMs,
      endMs: match.endTimeMs,
    }
  })
  return { query, count: matches.length, matches }
}

function isAudioActivityElement(element: unknown): element is VideoElement | AudioElement {
  return typeof element === 'object' && element !== null && 'type' in element && (element.type === 'video' || element.type === 'audio')
}

function pickAudioActivitySource(engine: EditorEngine, payload: AudioActivityPayload): AudioActivitySource {
  const project = engine.project
  if (payload.elementId) {
    const location = getElementLocation(project, payload.elementId)
    if (!location || !isAudioActivityElement(location.element)) {
      throw new Error(`Element "${payload.elementId}" is not a video or audio clip.`)
    }
    const asset = project.assets[location.element.assetId]
    if (!asset) throw new Error(`Element "${payload.elementId}" has no asset.`)
    return { asset, element: location.element, track: location.track }
  }

  for (const elementId of engine.selection.elementIds) {
    const location = getElementLocation(project, elementId)
    if (!location || !isAudioActivityElement(location.element)) continue
    const asset = project.assets[location.element.assetId]
    if (asset) return { asset, element: location.element, track: location.track }
  }

  const candidates = project.tracks.flatMap((track) =>
    track.elements
      .filter((element): element is VideoElement | AudioElement => isAudioActivityElement(element) && !!project.assets[element.assetId])
      .map((element) => ({ asset: project.assets[element.assetId]!, element, track })),
  )
  const source = candidates.find((candidate) => candidate.element.type === 'video') ?? candidates.find((candidate) => candidate.element.type === 'audio')
  if (!source) throw new Error('Add a video or audio clip to the timeline first.')
  return source
}

function audioActivityRange(source: AudioActivitySource, payload: AudioActivityPayload): SourceRange {
  const elementStartMs = source.element.trimStartMs
  const elementEndMs = elementStartMs + getSourceSpanMs(source.element)
  const assetEndMs = source.asset.durationMs ?? elementEndMs
  const maxEndMs = Math.min(assetEndMs, elementEndMs)
  const startMs = clamp(payload.startMs ?? elementStartMs, elementStartMs, maxEndMs)
  const endMs = clamp(payload.endMs ?? maxEndMs, startMs, maxEndMs)
  if (endMs <= startMs) {
    throw new Error('get_audio_activity requires a non-empty source range.')
  }
  return { startMs, endMs, durationMs: endMs - startMs }
}

function offsetWindow(window: AudioActivityWindow, offsetMs: number): AudioActivityWindow {
  return {
    ...window,
    startMs: window.startMs + offsetMs,
    endMs: window.endMs + offsetMs,
  }
}

function silentSummary(durationMs: number): AudioActivity['summary'] {
  return {
    soundMs: 0,
    silenceMs: durationMs,
    soundFraction: 0,
    silenceFraction: 1,
    peakRms: 0,
    peakAmplitude: 0,
  }
}

export async function handleGetAudioActivity(
  engine: EditorEngine,
  payload: AudioActivityPayload,
  analyzer: AudioActivityAnalyzer = analyzeAudioActivity,
): Promise<unknown> {
  const source = pickAudioActivitySource(engine, payload)
  const range = audioActivityRange(source, payload)
  const waveformBuckets = payload.includeWaveform === true ? Math.max(1, Math.floor(payload.waveformBuckets ?? 128)) : undefined
  const options: AudioActivityOptions = {
    startMs: range.startMs,
    endMs: range.endMs,
    ...(payload.frameMs !== undefined ? { frameMs: payload.frameMs } : {}),
    ...(payload.threshold !== undefined ? { threshold: payload.threshold } : {}),
    ...(payload.minSoundMs !== undefined ? { minSoundMs: payload.minSoundMs } : {}),
    ...(payload.minSilenceMs !== undefined ? { minSilenceMs: payload.minSilenceMs } : {}),
    ...(payload.paddingMs !== undefined ? { paddingMs: payload.paddingMs } : {}),
    ...(waveformBuckets !== undefined ? { waveformBuckets } : {}),
  }
  const activity = await analyzer(source.asset.src, options)
  const base = {
    elementId: source.element.id,
    trackId: source.track.id,
    trackName: source.track.name,
    asset: {
      id: source.asset.id,
      kind: source.asset.kind,
      ...(source.asset.name ? { name: source.asset.name } : {}),
      ...(source.asset.durationMs !== undefined ? { durationMs: source.asset.durationMs } : {}),
      ...(source.asset.mimeType ? { mimeType: source.asset.mimeType } : {}),
      ...(source.asset.width !== undefined ? { width: source.asset.width } : {}),
      ...(source.asset.height !== undefined ? { height: source.asset.height } : {}),
    },
    source: {
      startMs: range.startMs,
      endMs: range.endMs,
      durationMs: range.durationMs,
      elementStartMs: source.element.startMs,
      elementEndMs: source.element.startMs + source.element.durationMs,
      elementSourceStartMs: source.element.trimStartMs,
      elementSourceEndMs: source.element.trimStartMs + getSourceSpanMs(source.element),
      hasTimeMap: !!source.element.timeMap,
      reversed: !!source.element.reversed,
      timeBasis: 'source-ms',
    },
  }

  if (!activity) {
    return {
      ...base,
      hasAudio: false,
      durationMs: range.durationMs,
      soundWindows: [],
      silenceWindows: [
        {
          startMs: range.startMs,
          endMs: range.endMs,
          durationMs: range.durationMs,
          rms: 0,
          peakRms: 0,
          peakAmplitude: 0,
        },
      ],
      summary: silentSummary(range.durationMs),
    }
  }

  return {
    ...base,
    hasAudio: true,
    durationMs: activity.durationMs,
    soundWindows: activity.soundWindows.map((window) => offsetWindow(window, range.startMs)),
    silenceWindows: activity.silenceWindows.map((window) => offsetWindow(window, range.startMs)),
    summary: activity.summary,
    ...(activity.waveform ? { waveform: activity.waveform } : {}),
  }
}

function serializeError(error: unknown) {
  if (error instanceof CommandError || error instanceof ProjectFormatError || error instanceof OperatorError) {
    return { name: error.name, code: error.code, message: error.message }
  }
  return {
    name: error instanceof Error ? error.name : 'Error',
    message: error instanceof Error ? error.message : String(error),
  }
}

export async function handleLiveMcpRequest(engine: EditorEngine, ui: ReturnType<typeof useEditorUI>, request: BridgeRequest): Promise<unknown> {
  const context = { engine, ui, clipboard: editorClipboard }
  switch (request.type) {
    case 'get_summary':
      return summarizeEngine(engine)
    case 'get_project':
      return engine.toJSON()
    case 'get_media_context':
      return getProjectMediaContext(engine.project, {
        playback: engine.playback.state,
        selection: engine.selection,
      })
    case 'get_transcript':
      return getProjectTranscript(engine.project, request.payload)
    case 'search_transcript':
      return searchProjectTranscript(engine.project, request.payload.query)
    case 'ensure_transcript':
      return await ensureTranscriptForBridge(engine, request.payload)
    case 'get_audio_activity':
      return await handleGetAudioActivity(engine, request.payload)
    case 'list_commands':
      return listToolDefinitions()
    case 'apply_commands': {
      const commands = request.payload.commands.map(parseCommand)
      applyCommands(engine, commands)
      return { applied: commands.length, summary: summarizeEngine(engine) }
    }
    case 'list_operators':
      return listOperators({ engine }).map((operator) => ({
        id: operator.id,
        label: operator.label,
        category: operator.category,
        enabled: operator.enabled,
        disabledReason: operator.disabledReason,
        tool: liveMcpOperatorToolName(operator.id),
        description: operator.description,
      }))
    case 'list_actions':
      return listEditorActions().map((action) => ({
        id: action.id,
        label: action.label,
        description: action.description,
        category: action.category,
        enabled: isActionEnabled(action, context),
        shortcut: formatShortcut(action.shortcut),
        palette: action.palette ?? true,
        inputSchema: action.inputSchema,
        operator: action.operator?.id,
      }))
    case 'undo':
      return engine.undo()
    case 'redo':
      return engine.redo()
    case 'run_operator': {
      const { operatorId, input } = request.payload
      return await runOperator(parseOperatorId(operatorId), { engine }, input)
    }
    case 'dispatch_command': {
      const { commandName, input } = request.payload
      engine.dispatch(parseCommand({ ...input, type: commandName }))
      return null
    }
    case 'run_action': {
      const { actionId, input } = request.payload
      const action = getEditorAction(actionId)
      if (!action) throw new Error(`Unknown editor action "${actionId}".`)
      if (!isActionEnabled(action, context)) {
        throw new Error(`Editor action "${actionId}" is disabled.`)
      }
      return runEditorAction(action, { ...context, input, throwOnError: true }) ?? null
    }
    default: {
      const unhandled: never = request
      throw new Error(`Unknown live MCP request ${JSON.stringify(unhandled)}.`)
    }
  }
}

const storedBridgeConfigSchema = z.object({
  port: z.string(),
  token: z.string().nullable().catch(null),
})

interface BridgeLaunch {
  source: 'url' | 'storage'
  port: string
  token: string | null
}

const RECONNECT_DELAY_MS: Record<BridgeLaunch['source'], number> = { url: 1000, storage: 5000 }

function readStoredBridgeLaunch(): BridgeLaunch | null {
  try {
    const raw = window.sessionStorage.getItem(BRIDGE_CONFIG_STORAGE_KEY)
    if (!raw) return null
    const stored = storedBridgeConfigSchema.safeParse(JSON.parse(raw))
    if (!stored.success) return null
    return { source: 'storage', port: stored.data.port || DEFAULT_BRIDGE_PORT, token: stored.data.token }
  } catch {
    return null
  }
}

function rememberBridgeLaunch(launch: BridgeLaunch): void {
  try {
    window.sessionStorage.setItem(BRIDGE_CONFIG_STORAGE_KEY, JSON.stringify({ port: launch.port, token: launch.token }))
  } catch {}
}

function readBridgeLaunch(): BridgeLaunch | null {
  if (typeof window === 'undefined') return null
  const params = new URLSearchParams(window.location.search)
  const port = params.get('mcpBridge')
  if (port === null) return readStoredBridgeLaunch()
  return { source: 'url', port: port || DEFAULT_BRIDGE_PORT, token: params.get('mcpToken') }
}

function bridgeSocketUrl(launch: BridgeLaunch): string {
  const url = new URL(`ws://127.0.0.1:${launch.port}/mcut-mcp`)
  if (launch.token) url.searchParams.set('token', launch.token)
  return url.href
}

async function respondToBridgeFrame(socket: WebSocket, data: unknown, engine: EditorEngine, ui: ReturnType<typeof useEditorUI>): Promise<void> {
  const frame = parseBridgeFrame(data)
  if (!frame.ok) {
    socket.send(JSON.stringify({ id: frame.id, ok: false, error: frame.error }))
    return
  }
  const { request } = frame
  try {
    const result = await handleLiveMcpRequest(engine, ui, request)
    socket.send(JSON.stringify({ id: request.id, ok: true, result }))
  } catch (error) {
    socket.send(JSON.stringify({ id: request.id, ok: false, error: serializeError(error) }))
  }
}

function BridgeConnection({ launch }: { launch: BridgeLaunch }) {
  const engine = useEditor()
  const ui = useEditorUI()
  useWebSocket(
    bridgeSocketUrl(launch),
    {
      onOpen: (socket) => {
        socket.send(
          JSON.stringify({
            type: 'hello',
            payload: { projectName: engine.project.name, userAgent: window.navigator.userAgent },
          }),
        )
        if (launch.source === 'url') {
          rememberBridgeLaunch(launch)
          toast.success('Live MCP connected')
        }
      },
      onMessage: (socket, event) => {
        void respondToBridgeFrame(socket, event.data, engine, ui)
      },
    },
    { reconnectDelayMs: RECONNECT_DELAY_MS[launch.source] },
  )
  return null
}

export function LiveMcpBridge() {
  const [launch] = useState(readBridgeLaunch)
  return launch === null ? null : <BridgeConnection launch={launch} />
}

import { MCP_TOOL_INPUTS } from '@mcut/mcp-server/contract'
import { z } from 'zod'

const request = <Type extends string, Payload extends z.ZodType>(type: Type, payload: Payload) => z.object({ id: z.string(), type: z.literal(type), payload })

export const bridgeRequestSchema = z.discriminatedUnion('type', [
  request('get_summary', MCP_TOOL_INPUTS.get_summary.optional()),
  request('get_project', MCP_TOOL_INPUTS.get_project.optional()),
  request('get_media_context', MCP_TOOL_INPUTS.get_media_context.optional()),
  request('get_audio_activity', MCP_TOOL_INPUTS.get_audio_activity.default({})),
  request('get_transcript', MCP_TOOL_INPUTS.get_transcript.default({})),
  request('search_transcript', MCP_TOOL_INPUTS.search_transcript),
  request('ensure_transcript', MCP_TOOL_INPUTS.ensure_transcript.default({})),
  request('list_commands', MCP_TOOL_INPUTS.list_commands.optional()),
  request('apply_commands', MCP_TOOL_INPUTS.apply_commands),
  request('list_operators', MCP_TOOL_INPUTS.list_operators.optional()),
  request('run_operator', MCP_TOOL_INPUTS.run_operator),
  request('list_actions', MCP_TOOL_INPUTS.list_actions.optional()),
  request('run_action', MCP_TOOL_INPUTS.run_action),
  request('undo', MCP_TOOL_INPUTS.undo.optional()),
  request('redo', MCP_TOOL_INPUTS.redo.optional()),
  request(
    'dispatch_command',
    z.strictObject({
      commandName: z.string(),
      input: z.record(z.string(), z.unknown()).default({}),
    }),
  ),
])

export type BridgeRequest = z.infer<typeof bridgeRequestSchema>

export interface BridgeRequestError {
  name: 'BridgeRequestError'
  code: 'invalid-request'
  message: string
}

export type BridgeFrame = { ok: true; request: BridgeRequest } | { ok: false; id: string | undefined; error: BridgeRequestError }

const frameIdSchema = z.object({ id: z.string() })

function rejection(id: string | undefined, message: string): BridgeFrame {
  return { ok: false, id, error: { name: 'BridgeRequestError', code: 'invalid-request', message } }
}

export function parseBridgeFrame(raw: unknown): BridgeFrame {
  let value: unknown
  try {
    value = JSON.parse(String(raw))
  } catch {
    return rejection(undefined, 'Bridge frame is not valid JSON.')
  }
  const parsed = bridgeRequestSchema.safeParse(value)
  if (parsed.success) return { ok: true, request: parsed.data }
  const envelope = frameIdSchema.safeParse(value)
  return rejection(envelope.success ? envelope.data.id : undefined, z.prettifyError(parsed.error))
}

'use client'

import { extractAudioToWav } from '@mcut/media'
import { buildApplyCaptionsCommand, type TranscribeOptions, type TranscriptResult } from '@mcut/transcription'
import {
  getProjectCaptions,
  getProjectTranscript,
  rangesOverlap,
  type EditorEngine,
  type ElementAudioSource,
  type ProjectTranscriptContext,
  resolveElementAudioSource,
} from '@mcut/timeline'
import type { MCP_TOOL_INPUTS } from '@mcut/mcp-server/contract'
import type { z } from 'zod'
import { isLocalTranscriptionSupported, transcribeOnDevice } from './local-transcription'

type EnsureTranscriptPayload = z.infer<typeof MCP_TOOL_INPUTS.ensure_transcript>

export interface EnsureTranscriptDeps {
  isLocalTranscriptionSupported: () => boolean
  extractAudioToWav: (src: string) => Promise<Blob | null>
  transcribeOnDevice: (audio: Blob, options?: TranscribeOptions) => Promise<TranscriptResult>
}

export interface EnsureTranscriptResult {
  applied: boolean
  reason?: string
  source: {
    elementId: string
    assetId: string
    assetName?: string
    startMs: number
    endMs: number
    sourceStartMs: number
    sourceEndMs: number
  }
  transcript: ProjectTranscriptContext
}

const browserDeps: EnsureTranscriptDeps = {
  isLocalTranscriptionSupported,
  extractAudioToWav: (src) => extractAudioToWav(src),
  transcribeOnDevice,
}

function pickTranscriptionSource(engine: EditorEngine, payload: EnsureTranscriptPayload): ElementAudioSource {
  const project = engine.project
  if (payload.elementId) {
    const source = resolveElementAudioSource(project, payload.elementId)
    if (!source) throw new Error(`Element "${payload.elementId}" has no source audio.`)
    return source
  }

  for (const elementId of engine.selection.elementIds) {
    const source = resolveElementAudioSource(project, elementId)
    if (source) return source
  }

  const source = project.tracks
    .flatMap((track) => track.elements)
    .sort((a, b) => a.startMs - b.startMs)
    .map((element) => resolveElementAudioSource(project, element.id))
    .find((candidate): candidate is ElementAudioSource => candidate !== null)
  if (!source) throw new Error('Add a video, audio, or multicam clip with source audio to the timeline first.')
  return source
}

function assertBridgeTranscriptionSupported(source: ElementAudioSource): void {
  if (source.reversed) {
    throw new Error('Bridge transcription does not support reversed clips yet.')
  }
  if (source.timeMap) {
    throw new Error('Bridge transcription does not support speed-ramped clips yet.')
  }
}

function overlappingCaptions(engine: EditorEngine, source: ElementAudioSource) {
  return getProjectCaptions(engine.project).filter(({ caption }) =>
    rangesOverlap(caption.startMs, caption.durationMs, source.timelineStartMs, source.timelineDurationMs),
  )
}

function sourceResult(source: ElementAudioSource): EnsureTranscriptResult['source'] {
  return {
    elementId: source.elementId,
    assetId: source.asset.id,
    ...(source.asset.name ? { assetName: source.asset.name } : {}),
    startMs: source.timelineStartMs,
    endMs: source.timelineStartMs + source.timelineDurationMs,
    sourceStartMs: source.sourceStartMs,
    sourceEndMs: source.sourceEndMs,
  }
}

export async function ensureTranscriptForBridge(
  engine: EditorEngine,
  payload: EnsureTranscriptPayload,
  deps: EnsureTranscriptDeps = browserDeps,
): Promise<EnsureTranscriptResult> {
  const source = pickTranscriptionSource(engine, payload)
  const sourceInfo = sourceResult(source)
  const existing = overlappingCaptions(engine, source)

  if (!payload.replace && existing.length > 0) {
    return {
      applied: false,
      reason: 'Transcript captions already overlap the target clip.',
      source: sourceInfo,
      transcript: getProjectTranscript(engine.project, { includeWords: true }),
    }
  }

  assertBridgeTranscriptionSupported(source)
  if (!deps.isLocalTranscriptionSupported()) {
    throw new Error('Local Whisper transcription is not supported in this browser. Use a WebGPU-capable browser with enough memory.')
  }

  const wav = await deps.extractAudioToWav(source.asset.src)
  if (!wav) {
    throw new Error(`"${source.asset.name ?? source.asset.id}" has no audio track.`)
  }

  const options = payload.language ? { language: payload.language } : undefined
  const result = await deps.transcribeOnDevice(wav, options)
  const command = buildApplyCaptionsCommand(result, {
    replace: false,
    timeOffsetMs: source.timelineStartMs,
    sourceStartMs: source.sourceStartMs,
    sourceEndMs: source.sourceEndMs,
  })
  if (!Array.isArray(command.captions) || command.captions.length === 0) {
    throw new Error('Transcription produced no captions for the target clip.')
  }

  engine.transact(() => {
    if (payload.replace) {
      for (const { caption } of overlappingCaptions(engine, source)) {
        engine.dispatch({ type: 'removeElement', elementId: caption.id })
      }
    }
    engine.dispatch(command)
  })

  return {
    applied: true,
    source: sourceInfo,
    transcript: getProjectTranscript(engine.project, { includeWords: true }),
  }
}

import { collectSnapTargets as collectTimelineSnapTargets, type Project, type SnapTarget } from '@mcut/timeline'

export { snapClip, snapTime } from '@mcut/timeline'
export type { SnapClipResult, SnapOptions, SnapResult, SnapTarget } from '@mcut/timeline'

export function collectSnapTargets(project: Project, playheadMs: number, excludeElementIds: ReadonlySet<string> = new Set()): SnapTarget[] {
  return collectTimelineSnapTargets(project, { playheadMs, excludeElementIds })
}

export function pointerToTimelineMs(clientX: number, laneRect: { left: number }, pxPerMs: number): number {
  return Math.max(0, Math.round((clientX - laneRect.left) / pxPerMs))
}

'use client'

import { createContext, useContext } from 'react'
import { useDisposable, useEditor, useLatest } from '@mcut/react'
import {
  canPlaceIgnoring,
  collectClipDragBases,
  computeSlipRange,
  planAutoCrossfade,
  planDuplicateClipsToNewTracks,
  retimeSequentialCollage,
  resolveToolMode,
  type ClipDragBase,
  type ClipDragMode,
} from '@mcut/editor'
import { createTrackId, getElementLocation, MIN_ELEMENT_DURATION_MS, type ElementId, type Track } from '@mcut/timeline'
import { getEditorPrefs, useEditorUI } from './editor-ui'
import { collectSnapTargets, snapClip, snapTime, type SnapTarget } from './timeline-snap'

type Engine = ReturnType<typeof useEditor>

export type { ClipDragMode } from '@mcut/editor'

export const TRACK_HEIGHT = 56
export const RULER_HEIGHT = 28
export const NEW_TRACK_LANE_HEIGHT = 36
export const SNAP_PX = 8

const DRAG_THRESHOLD_PX = 4
const AUTO_SCROLL_EDGE_PX = 36
const AUTO_SCROLL_MAX_PX = 18

export interface ClipDragBeginOptions {
  mode: ClipDragMode
  ids: ElementId[]
  ignoreIds?: ElementId[]
  duplicateOnDrag: boolean
}

export interface ClipDragPrefs {
  pxPerMs: number
  snapEnabled: boolean
  autoCrossfade: boolean
}

export interface ClipDragDeps {
  engine: Engine
  prefs: () => ClipDragPrefs
  timelineHeaderPx: () => number
  setSnapGuideMs: (ms: number | null) => void
  scrollerRef: React.RefObject<HTMLElement | null>
}

interface ClipDragGesture {
  mode: ClipDragMode
  pointerId: number
  ids: ElementId[]
  bases: Map<ElementId, ClipDragBase>
  startClientX: number
  startClientY: number
  startScrollLeft: number
  startScrollTop: number
  lastClientX: number
  lastClientY: number
  lastAltKey: boolean
  active: boolean
  duplicateOnDrag: boolean
  duplicated: boolean
  createdTrackIds: Track['id'][]
  ignore: ReadonlySet<string>
  targets: SnapTarget[]
  appliedDeltaMs: number
  rollTargetId: ElementId | null
  slipRange: { minMs: number; maxMs: number } | null
}

function duplicateClipsToNewTracks(
  engine: Engine,
  ids: readonly ElementId[],
): { ids: ElementId[]; bases: Map<ElementId, ClipDragBase>; createdTrackIds: Track['id'][] } | null {
  const plan = planDuplicateClipsToNewTracks(engine.project, ids)
  if (!plan) return null
  for (const command of plan.commands) {
    engine.dispatch(command)
  }
  return {
    ids: plan.ids,
    bases: collectClipDragBases(engine.project, plan.ids),
    createdTrackIds: plan.createdTrackIds,
  }
}

function removeEmptyCreatedTracks(engine: Engine, trackIds: readonly Track['id'][]) {
  for (const trackId of trackIds) {
    const track = engine.project.tracks.find((t) => t.id === trackId)
    if (track && track.elements.length === 0) {
      engine.dispatch({ type: 'removeTrack', trackId })
    }
  }
}

function isDirectTrimMode(mode: ClipDragMode): boolean {
  return mode === 'trim-start' || mode === 'trim-end'
}

function slipDeltaOpposingThePointer(pointerDeltaMs: number): number {
  return -Math.round(pointerDeltaMs)
}

function edgeScrollSpeed(pos: number, min: number, max: number): number {
  if (pos < min + AUTO_SCROLL_EDGE_PX) {
    return -Math.min(AUTO_SCROLL_MAX_PX, ((min + AUTO_SCROLL_EDGE_PX - pos) / AUTO_SCROLL_EDGE_PX) * AUTO_SCROLL_MAX_PX)
  }
  if (pos > max - AUTO_SCROLL_EDGE_PX) {
    return Math.min(AUTO_SCROLL_MAX_PX, ((pos - (max - AUTO_SCROLL_EDGE_PX)) / AUTO_SCROLL_EDGE_PX) * AUTO_SCROLL_MAX_PX)
  }
  return 0
}

export class ClipDragController {
  constructor(private readonly deps: ClipDragDeps) {}

  private gesture: ClipDragGesture | null = null
  private autoScrollFrame: number | null = null
  private updateFrame: number | null = null
  private pendingMove = false
  private previousBodyUserSelect: string | null = null
  private capture: { element: Element; pointerId: number } | null = null

  begin(event: { clientX: number; clientY: number; pointerId: number }, options: ClipDragBeginOptions): void {
    this.cancel()
    const project = this.deps.engine.project
    const bases = collectClipDragBases(project, options.ids)
    if (options.ids.length === 0 || !bases.has(options.ids[0]!)) return
    const resolved = resolveToolMode(project, options.mode, options.ids)
    const scroller = this.deps.scrollerRef.current
    this.gesture = {
      mode: resolved.mode,
      pointerId: event.pointerId,
      ids: options.ids,
      bases,
      startClientX: event.clientX,
      startClientY: event.clientY,
      startScrollLeft: scroller?.scrollLeft ?? 0,
      startScrollTop: scroller?.scrollTop ?? 0,
      lastClientX: event.clientX,
      lastClientY: event.clientY,
      lastAltKey: options.duplicateOnDrag,
      active: false,
      duplicateOnDrag: options.duplicateOnDrag,
      duplicated: false,
      createdTrackIds: [],
      ignore: new Set<string>([...options.ids, ...(options.ignoreIds ?? [])]),
      targets: [],
      appliedDeltaMs: 0,
      rollTargetId: resolved.rollTargetId,
      slipRange: resolved.mode === 'slip' ? computeSlipRange(project, options.ids) : null,
    }
    this.attach()
  }

  get dragging(): boolean {
    return this.gesture?.active ?? false
  }

  dispose(): void {
    this.cancel()
  }

  private onPointerMove = (event: PointerEvent) => {
    const gesture = this.gesture
    if (!gesture || event.pointerId !== gesture.pointerId) return
    if ((event.buttons & 1) === 0) {
      this.finish()
      return
    }
    gesture.lastClientX = event.clientX
    gesture.lastClientY = event.clientY
    gesture.lastAltKey = event.altKey
    if (!gesture.active) {
      const travelled = Math.hypot(event.clientX - gesture.startClientX, event.clientY - gesture.startClientY)
      const bodyGesture = gesture.mode === 'move' || gesture.mode === 'slip' || gesture.mode === 'slide'
      const threshold = bodyGesture ? DRAG_THRESHOLD_PX : 1
      if (travelled < threshold) return
      this.activate()
    }
    this.scheduleUpdate()
  }

  private scheduleUpdate(): void {
    if (this.updateFrame !== null) {
      this.pendingMove = true
      return
    }
    this.update()
    this.updateFrame = requestAnimationFrame(() => {
      this.updateFrame = null
      if (this.pendingMove) {
        this.pendingMove = false
        this.update()
      }
    })
  }

  private onPointerUp = (event: PointerEvent) => {
    const gesture = this.gesture
    if (!gesture || event.pointerId !== gesture.pointerId) return
    this.finish()
  }

  private onPointerCancel = (event: PointerEvent) => {
    const gesture = this.gesture
    if (!gesture || event.pointerId !== gesture.pointerId) return
    this.cancel()
  }

  private onKeyDown = (event: KeyboardEvent) => {
    if (event.key !== 'Escape' || !this.gesture) return
    event.preventDefault()
    event.stopPropagation()
    this.cancel()
  }

  private onWindowBlur = () => {
    this.cancel()
  }

  private attach(): void {
    window.addEventListener('pointermove', this.onPointerMove)
    window.addEventListener('pointerup', this.onPointerUp)
    window.addEventListener('pointercancel', this.onPointerCancel)
    window.addEventListener('keydown', this.onKeyDown, true)
    window.addEventListener('blur', this.onWindowBlur)
  }

  private detach(): void {
    window.removeEventListener('pointermove', this.onPointerMove)
    window.removeEventListener('pointerup', this.onPointerUp)
    window.removeEventListener('pointercancel', this.onPointerCancel)
    window.removeEventListener('keydown', this.onKeyDown, true)
    window.removeEventListener('blur', this.onWindowBlur)
    if (this.capture !== null) {
      try {
        this.capture.element.releasePointerCapture(this.capture.pointerId)
      } catch {}
      this.capture = null
    }
    if (this.autoScrollFrame !== null) {
      cancelAnimationFrame(this.autoScrollFrame)
      this.autoScrollFrame = null
    }
    if (this.updateFrame !== null) {
      cancelAnimationFrame(this.updateFrame)
      this.updateFrame = null
    }
    this.pendingMove = false
    if (this.previousBodyUserSelect !== null) {
      document.body.style.userSelect = this.previousBodyUserSelect
      this.previousBodyUserSelect = null
    }
  }

  private activate(): void {
    const gesture = this.gesture!
    gesture.active = true
    this.deps.engine.beginTransaction()
    const captureElement = this.deps.scrollerRef.current ?? document.body
    try {
      captureElement.setPointerCapture(gesture.pointerId)
      this.capture = { element: captureElement, pointerId: gesture.pointerId }
    } catch {
      this.capture = null
    }
    this.previousBodyUserSelect = document.body.style.userSelect
    document.body.style.userSelect = 'none'
    if (gesture.duplicateOnDrag && !gesture.duplicated) {
      const duplicated = duplicateClipsToNewTracks(this.deps.engine, gesture.ids)
      if (duplicated) {
        gesture.ids = duplicated.ids
        gesture.bases = duplicated.bases
        gesture.createdTrackIds = duplicated.createdTrackIds
        gesture.duplicated = true
        this.deps.engine.select(duplicated.ids)
        gesture.ignore = new Set<string>(gesture.ids)
      }
    }
    gesture.targets = collectSnapTargets(this.deps.engine.project, this.deps.engine.playback.state.currentTimeMs, gesture.ignore)
    this.startAutoScroll()
  }

  private finish(): void {
    const gesture = this.gesture
    if (!gesture) return
    if (gesture.active && this.pendingMove) {
      this.pendingMove = false
      this.update()
    }
    this.gesture = null
    this.detach()
    if (gesture.active) {
      removeEmptyCreatedTracks(this.deps.engine, gesture.createdTrackIds)
      this.maybeAutoCrossfade(gesture)
      const shouldRetimeCollage = isDirectTrimMode(gesture.mode) && gesture.ids.some((id) => getElementLocation(this.deps.engine.project, id)?.element.groupId)
      if (shouldRetimeCollage) {
        try {
          retimeSequentialCollage(this.deps.engine)
        } catch {}
      }
      this.deps.engine.endTransaction()
      this.deps.setSnapGuideMs(null)
    }
  }

  private maybeAutoCrossfade(gesture: ClipDragGesture): void {
    const { engine } = this.deps
    const { pxPerMs, autoCrossfade } = this.deps.prefs()
    if (!autoCrossfade || gesture.mode !== 'move' || gesture.ids.length !== 1) return
    const anchorId = gesture.ids[0]!
    const base = gesture.bases.get(anchorId)
    if (!base) return
    const scroller = this.deps.scrollerRef.current
    const scrollDx = (scroller?.scrollLeft ?? gesture.startScrollLeft) - gesture.startScrollLeft
    const desiredStartMs = base.startMs + (gesture.lastClientX - gesture.startClientX + scrollDx) / pxPerMs
    const command = planAutoCrossfade(engine.project, { elementId: anchorId, desiredStartMs })
    if (command) {
      try {
        engine.dispatch(command)
      } catch {}
    }
  }

  private cancel(): void {
    const gesture = this.gesture
    if (!gesture) return
    this.gesture = null
    this.detach()
    if (gesture.active) {
      this.deps.engine.cancelTransaction()
      this.deps.setSnapGuideMs(null)
    }
  }

  private startAutoScroll(): void {
    if (this.autoScrollFrame !== null) return
    const tick = () => {
      const gesture = this.gesture
      const scroller = this.deps.scrollerRef.current
      if (!gesture?.active || !scroller) {
        this.autoScrollFrame = null
        return
      }
      const rect = scroller.getBoundingClientRect()
      const dx = edgeScrollSpeed(gesture.lastClientX, rect.left + this.deps.timelineHeaderPx(), rect.right)
      const dy = edgeScrollSpeed(gesture.lastClientY, rect.top + RULER_HEIGHT, rect.bottom)
      let scrolled = false
      if (dx !== 0) {
        const next = Math.max(0, Math.min(scroller.scrollLeft + dx, scroller.scrollWidth - scroller.clientWidth))
        if (next !== scroller.scrollLeft) {
          scroller.scrollLeft = next
          scrolled = true
        }
      }
      if (dy !== 0) {
        const next = Math.max(0, Math.min(scroller.scrollTop + dy, scroller.scrollHeight - scroller.clientHeight))
        if (next !== scroller.scrollTop) {
          scroller.scrollTop = next
          scrolled = true
        }
      }
      if (scrolled) this.update()
      this.autoScrollFrame = requestAnimationFrame(tick)
    }
    this.autoScrollFrame = requestAnimationFrame(tick)
  }

  private update(): void {
    const gesture = this.gesture
    if (!gesture?.active) return
    const { engine, setSnapGuideMs } = this.deps
    const { pxPerMs, snapEnabled } = this.deps.prefs()
    const scroller = this.deps.scrollerRef.current
    const scrollDx = (scroller?.scrollLeft ?? gesture.startScrollLeft) - gesture.startScrollLeft
    const deltaRawMs = (gesture.lastClientX - gesture.startClientX + scrollDx) / pxPerMs
    const liveProject = engine.project
    const anchorId = gesture.ids[0]!
    const anchorBase = gesture.bases.get(anchorId)!
    const { ignore, targets } = gesture
    const thresholdMs = SNAP_PX / pxPerMs

    try {
      if (gesture.mode === 'move') {
        const snapping = snapEnabled && !(gesture.lastAltKey && !gesture.duplicated)
        const snapped = snapClip(anchorBase.startMs + deltaRawMs, anchorBase.durationMs, targets, thresholdMs, {
          enabled: snapping,
          fps: liveProject.fps,
        })
        let guide = snapped.guideMs
        let deltaMs = Math.round(snapped.ms - anchorBase.startMs)
        const minStart = Math.min(...gesture.ids.map((id) => gesture.bases.get(id)!.startMs))
        deltaMs = Math.max(deltaMs, -minStart)

        if (gesture.ids.length === 1) {
          const trackCount = liveProject.tracks.length
          let targetIndex = anchorBase.trackIndex
          if (scroller) {
            const rect = scroller.getBoundingClientRect()
            const contentY = gesture.lastClientY - rect.top + scroller.scrollTop
            const visualRow = Math.floor((contentY - RULER_HEIGHT - NEW_TRACK_LANE_HEIGHT) / TRACK_HEIGHT)
            targetIndex = trackCount - 1 - visualRow
          }
          let targetTrack: Track | undefined
          if ((targetIndex >= trackCount || targetIndex < 0) && gesture.createdTrackIds.length === 0) {
            const trackId = createTrackId()
            engine.dispatch({
              type: 'addTrack',
              id: trackId,
              ...(targetIndex < 0 ? { index: 0 } : {}),
            })
            gesture.createdTrackIds.push(trackId)
            targetTrack = engine.project.tracks.find((track) => track.id === trackId)
          } else {
            targetIndex = Math.max(0, Math.min(targetIndex, trackCount - 1))
            targetTrack = liveProject.tracks[targetIndex]
          }
          if (!targetTrack) return
          if (targetTrack.locked) return
          let startMs = anchorBase.startMs + deltaMs
          if (targetTrack.magnetic) {
            startMs = Math.max(0, Math.round(anchorBase.startMs + deltaRawMs))
            guide = null
          } else if (!canPlaceIgnoring(targetTrack, startMs, anchorBase.durationMs, ignore)) {
            setSnapGuideMs(null)
            return
          }
          engine.dispatch({
            type: 'moveElement',
            elementId: anchorId,
            startMs,
            toTrackId: targetTrack.id,
          })
        } else {
          const placements = gesture.ids.map((id) => {
            const base = gesture.bases.get(id)!
            return {
              id,
              startMs: base.startMs + deltaMs,
              durationMs: base.durationMs,
              track: liveProject.tracks[base.trackIndex],
            }
          })
          const allFit = placements.every((p) => p.track && (p.track.magnetic || canPlaceIgnoring(p.track, p.startMs, p.durationMs, ignore)))
          if (allFit) {
            for (const p of placements) {
              engine.dispatch({ type: 'moveElement', elementId: p.id, startMs: p.startMs })
            }
          } else {
            guide = null
          }
        }
        setSnapGuideMs(guide)
        return
      }

      const snapping = snapEnabled && !gesture.lastAltKey

      if (gesture.mode === 'slip') {
        const range = gesture.slipRange ?? { minMs: -Infinity, maxMs: Infinity }
        const wanted = Math.max(range.minMs, Math.min(range.maxMs, slipDeltaOpposingThePointer(deltaRawMs)))
        const stepMs = wanted - gesture.appliedDeltaMs
        if (stepMs !== 0) {
          for (const id of gesture.ids) {
            const element = getElementLocation(liveProject, id)?.element
            if (!element) continue
            if (element.type !== 'video' && element.type !== 'audio' && element.type !== 'multicam') continue
            engine.dispatch({ type: 'slipElement', elementId: id, deltaMs: stepMs })
          }
          gesture.appliedDeltaMs = wanted
        }
        setSnapGuideMs(null)
        return
      }

      if (gesture.mode === 'slide') {
        const snapped = snapClip(anchorBase.startMs + deltaRawMs, anchorBase.durationMs, targets, thresholdMs, {
          enabled: snapping,
          fps: liveProject.fps,
        })
        const wanted = Math.round(snapped.ms) - anchorBase.startMs
        const stepMs = wanted - gesture.appliedDeltaMs
        if (stepMs !== 0) {
          engine.dispatch({ type: 'slideElement', elementId: anchorId, deltaMs: stepMs })
          gesture.appliedDeltaMs = wanted
        }
        setSnapGuideMs(gesture.appliedDeltaMs === wanted ? snapped.guideMs : null)
        return
      }

      if (gesture.mode === 'roll-start' || gesture.mode === 'roll-end') {
        const cutBaseMs = gesture.mode === 'roll-end' ? anchorBase.startMs + anchorBase.durationMs : anchorBase.startMs
        const snapped = snapTime(cutBaseMs + deltaRawMs, targets, thresholdMs, {
          enabled: snapping,
          fps: liveProject.fps,
        })
        const wanted = Math.round(snapped.ms) - cutBaseMs
        const rollId = gesture.mode === 'roll-end' ? anchorId : gesture.rollTargetId
        if (!rollId) return
        const stepMs = wanted - gesture.appliedDeltaMs
        if (stepMs !== 0) {
          engine.dispatch({ type: 'rollEdit', elementId: rollId, deltaMs: stepMs })
          gesture.appliedDeltaMs = wanted
        }
        setSnapGuideMs(gesture.appliedDeltaMs === wanted ? snapped.guideMs : null)
        return
      }

      if (gesture.mode === 'ripple-start' || gesture.mode === 'ripple-end') {
        const edge = gesture.mode === 'ripple-end' ? ('end' as const) : ('start' as const)
        const edgeBaseMs = edge === 'end' ? anchorBase.startMs + anchorBase.durationMs : anchorBase.startMs
        const rippleTargets = targets.filter((t) => t.kind === 'marker' || t.kind === 'playhead' || t.kind === 'origin')
        const snapped = snapTime(edgeBaseMs + deltaRawMs, rippleTargets, thresholdMs, {
          enabled: snapping,
          fps: liveProject.fps,
        })
        const wanted = Math.round(snapped.ms) - edgeBaseMs
        const stepMs = wanted - gesture.appliedDeltaMs
        if (stepMs !== 0) {
          engine.dispatch({ type: 'rippleTrim', elementId: anchorId, edge, deltaMs: stepMs })
          gesture.appliedDeltaMs = wanted
        }
        setSnapGuideMs(gesture.appliedDeltaMs === wanted ? snapped.guideMs : null)
        return
      }

      const members = gesture.ids.flatMap((id) => {
        const base = gesture.bases.get(id)
        if (!base) return []
        const element = getElementLocation(liveProject, id)?.element
        const asset = element && 'assetId' in element ? liveProject.assets[element.assetId] : undefined
        return [
          {
            id,
            base,
            element,
            assetDurationMs: asset?.durationMs,
            track: liveProject.tracks[base.trackIndex],
          },
        ]
      })
      const allFit = (startMs: (b: ClipDragBase) => number, durationMs: (b: ClipDragBase) => number) =>
        members.every(({ base, track }) => track && canPlaceIgnoring(track, startMs(base), durationMs(base), ignore))

      if (gesture.mode === 'trim-end') {
        const endSnap = snapTime(anchorBase.startMs + anchorBase.durationMs + deltaRawMs, targets, thresholdMs, {
          enabled: snapping,
          fps: liveProject.fps,
        })
        const wantedDelta = Math.round(endSnap.ms) - (anchorBase.startMs + anchorBase.durationMs)
        let deltaMs = wantedDelta
        for (const { base, assetDurationMs } of members) {
          if (!base.hasTimeMap && assetDurationMs !== undefined && base.trimStartMs !== undefined) {
            deltaMs = Math.min(deltaMs, base.reversed ? base.trimStartMs : assetDurationMs - base.trimStartMs - base.durationMs)
          }
          deltaMs = Math.max(deltaMs, MIN_ELEMENT_DURATION_MS - base.durationMs)
        }
        const fits = allFit(
          (b) => b.startMs,
          (b) => b.durationMs + deltaMs,
        )
        if (fits) {
          for (const { id, base, element } of members) {
            if (!element) continue
            const stepMs = base.startMs + base.durationMs + deltaMs - (element.startMs + element.durationMs)
            if (stepMs !== 0) {
              engine.dispatch({ type: 'trimEdge', elementId: id, edge: 'end', deltaMs: stepMs })
            }
          }
        }
        setSnapGuideMs(fits && deltaMs === wantedDelta ? endSnap.guideMs : null)
        return
      }

      const startSnap = snapTime(anchorBase.startMs + deltaRawMs, targets, thresholdMs, {
        enabled: snapping,
        fps: liveProject.fps,
      })
      const wantedShift = Math.round(startSnap.ms) - anchorBase.startMs
      let shift = wantedShift
      for (const { base, assetDurationMs } of members) {
        shift = Math.max(shift, -base.startMs)
        if (!base.hasTimeMap && base.trimStartMs !== undefined) {
          shift = Math.max(shift, base.reversed && assetDurationMs !== undefined ? -(assetDurationMs - base.trimStartMs - base.durationMs) : -base.trimStartMs)
        }
        if (base.hasTimeMap && base.reversed) shift = Math.max(shift, 0)
        shift = Math.min(shift, base.durationMs - MIN_ELEMENT_DURATION_MS)
      }
      const fits = allFit(
        (b) => b.startMs + shift,
        (b) => b.durationMs - shift,
      )
      if (fits) {
        for (const { id, base, element } of members) {
          if (!element) continue
          const stepMs = base.startMs + shift - element.startMs
          if (stepMs !== 0) {
            engine.dispatch({ type: 'trimEdge', elementId: id, edge: 'start', deltaMs: stepMs })
          }
        }
      }
      setSnapGuideMs(fits && shift === wantedShift ? startSnap.guideMs : null)
    } catch {}
  }
}

const ClipDragContext = createContext<ClipDragController | null>(null)

export const ClipDragProvider = ClipDragContext.Provider

export function useClipDragController(): ClipDragController {
  const engine = useEditor()
  const { setSnapGuideMs, timelineScrollRef, timelineHeaderPx } = useEditorUI()
  const latestHeaderPx = useLatest(timelineHeaderPx)
  return useDisposable(
    () =>
      new ClipDragController({
        engine,
        prefs: getEditorPrefs,
        timelineHeaderPx: () => latestHeaderPx.current,
        setSnapGuideMs,
        scrollerRef: timelineScrollRef,
      }),
  )
}

export function useClipDrag(): ClipDragController {
  const controller = useContext(ClipDragContext)
  if (!controller) throw new Error('useClipDrag must be used inside <ClipDragProvider>')
  return controller
}

import { parseProject, type AssetRef, type Project } from "@mcut/timeline";
import {
  isMediaStoreSupported,
  loadMediaBlob,
  pruneMediaBlobs,
  saveMediaBlob,
} from "@mcut/media";

const DB_NAME = "mcut-editor";
const DB_VERSION = 2;
const KV_STORE = "kv";
const ASSET_STORE = "assets";
const PROJECT_STORE = "projects";
const LEGACY_PROJECT_KEY = "project";
const ACTIVE_PROJECT_KEY = "activeProjectId";

interface StoredAsset {
  id: string;
  blob: Blob;
}

interface StoredProject {
  id: string;
  name: string;
  createdMs: number;
  updatedMs: number;
  durationMs: number;
  assetCount: number;
  thumbnail?: Blob;
  project: unknown;
}

export type ProjectListEntry = Omit<StoredProject, "project">;

function projectDurationMs(project: Project): number {
  let end = 0;
  for (const track of project.tracks) {
    for (const element of track.elements) {
      end = Math.max(end, element.startMs + element.durationMs);
    }
  }
  return end;
}

function hasContent(project: Project): boolean {
  return (
    Object.keys(project.assets).length > 0 ||
    project.tracks.some((track) => track.elements.length > 0)
  );
}

function toStoredProject(project: Project, previous?: StoredProject): StoredProject {
  const now = Date.now();
  return {
    id: project.id,
    name: project.name,
    createdMs: previous?.createdMs ?? now,
    updatedMs: now,
    durationMs: projectDurationMs(project),
    assetCount: Object.keys(project.assets).length,
    thumbnail: previous?.thumbnail,
    project: JSON.parse(JSON.stringify(project)),
  };
}

function openDb(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onupgradeneeded = () => {
      const db = request.result;
      const tx = request.transaction!;
      if (!db.objectStoreNames.contains(KV_STORE)) db.createObjectStore(KV_STORE);
      if (!db.objectStoreNames.contains(ASSET_STORE)) {
        db.createObjectStore(ASSET_STORE, { keyPath: "id" });
      }
      if (!db.objectStoreNames.contains(PROJECT_STORE)) {
        db.createObjectStore(PROJECT_STORE, { keyPath: "id" });
        const kv = tx.objectStore(KV_STORE);
        const read = kv.get(LEGACY_PROJECT_KEY);
        read.onsuccess = () => {
          const raw = read.result;
          if (!raw) return;
          try {
            const project = parseProject(raw);
            tx.objectStore(PROJECT_STORE).put(toStoredProject(project));
            kv.put(project.id, ACTIVE_PROJECT_KEY);
            kv.delete(LEGACY_PROJECT_KEY);
          } catch {
            kv.delete(LEGACY_PROJECT_KEY);
          }
        };
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function txDone(tx: IDBTransaction): Promise<void> {
  return new Promise((resolve, reject) => {
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
    tx.onabort = () => reject(tx.error);
  });
}

function getRequest<T>(request: IDBRequest<T>): Promise<T> {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

export async function requestPersistentStorage(): Promise<boolean> {
  try {
    return (await navigator.storage?.persist?.()) ?? false;
  } catch {
    return false;
  }
}

export async function saveProjectSnapshot(project: Project): Promise<void> {
  if (!hasContent(project)) return;
  const db = await openDb();
  let keepHashes = new Set<string>();
  try {
    const previousTx = db.transaction(PROJECT_STORE, "readonly");
    const previous = (await getRequest(previousTx.objectStore(PROJECT_STORE).get(project.id))) as
      | StoredProject
      | undefined;

    const saveTx = db.transaction([KV_STORE, PROJECT_STORE], "readwrite");
    saveTx.objectStore(PROJECT_STORE).put(toStoredProject(project, previous));
    saveTx.objectStore(KV_STORE).put(project.id, ACTIVE_PROJECT_KEY);
    await txDone(saveTx);

    const refsTx = db.transaction([PROJECT_STORE, ASSET_STORE], "readonly");
    const projectStore = refsTx.objectStore(PROJECT_STORE);
    const assetStore = refsTx.objectStore(ASSET_STORE);
    const [stored, keys] = await Promise.all([
      getRequest(projectStore.getAll()) as Promise<StoredProject[]>,
      getRequest(assetStore.getAllKeys()),
    ]);
    const refs = collectReferencedAssets(stored);
    keepHashes = refs.keepHashes;
    const staleKeys = keys.filter((key) => !refs.keepAssetIds.has(String(key)));
    if (staleKeys.length > 0) {
      const pruneTx = db.transaction(ASSET_STORE, "readwrite");
      const pruneStore = pruneTx.objectStore(ASSET_STORE);
      for (const key of staleKeys) pruneStore.delete(key);
      await txDone(pruneTx);
    }
  } finally {
    db.close();
  }
  await pruneMediaBlobs(keepHashes).catch(() => 0);
}

function collectReferencedAssets(
  stored: StoredProject[],
): { keepAssetIds: Set<string>; keepHashes: Set<string> } {
  const keepAssetIds = new Set<string>();
  const keepHashes = new Set<string>();
  for (const record of stored) {
    const assets = (record.project as Project | undefined)?.assets ?? {};
    for (const [id, asset] of Object.entries(assets)) {
      keepAssetIds.add(id);
      if (asset.hash) keepHashes.add(asset.hash);
    }
  }
  return { keepAssetIds, keepHashes };
}

export async function saveAssetBlob(asset: AssetRef | string, blob: Blob): Promise<void> {
  const assetId = typeof asset === "string" ? asset : asset.id;
  const hash = typeof asset === "string" ? undefined : asset.hash;
  if (hash && isMediaStoreSupported()) {
    const stored = await saveMediaBlob(hash, blob).catch(() => false);
    if (stored) return;
  }
  const db = await openDb();
  try {
    const tx = db.transaction(ASSET_STORE, "readwrite");
    tx.objectStore(ASSET_STORE).put({ id: assetId, blob } satisfies StoredAsset);
    await txDone(tx);
  } finally {
    db.close();
  }
}

export async function listProjects(): Promise<ProjectListEntry[]> {
  const db = await openDb();
  try {
    const tx = db.transaction(PROJECT_STORE, "readonly");
    const stored = (await getRequest(tx.objectStore(PROJECT_STORE).getAll())) as StoredProject[];
    return stored
      .map((record) => ({
        id: record.id,
        name: record.name,
        createdMs: record.createdMs,
        updatedMs: record.updatedMs,
        durationMs: record.durationMs,
        assetCount: record.assetCount,
        ...(record.thumbnail ? { thumbnail: record.thumbnail } : {}),
      }))
      .sort((a, b) => b.updatedMs - a.updatedMs);
  } catch {
    return [];
  } finally {
    db.close();
  }
}

export interface RestoredSession {
  project: Project;
  missingAssetIds: string[];
}

export async function loadProject(id: string): Promise<RestoredSession | null> {
  const db = await openDb();
  try {
    const projectTx = db.transaction(PROJECT_STORE, "readonly");
    const record = (await getRequest(projectTx.objectStore(PROJECT_STORE).get(id))) as
      | StoredProject
      | undefined;
    if (!record) return null;
    const project = parseProject(record.project);
    if (!hasContent(project)) return null;

    const assetTx = db.transaction(ASSET_STORE, "readonly");
    const stored = (await getRequest(assetTx.objectStore(ASSET_STORE).getAll())) as StoredAsset[];
    const blobs = new Map(stored.map((s) => [s.id, s.blob]));
    const missingAssetIds: string[] = [];
    const assets = { ...project.assets };
    for (const [assetId, asset] of Object.entries(assets)) {
      const blob =
        (asset.hash ? await loadMediaBlob(asset.hash).catch(() => null) : null) ??
        blobs.get(assetId);
      if (blob) {
        assets[assetId] = { ...asset, src: URL.createObjectURL(blob) };
      } else if (asset.src.startsWith("blob:")) {
        missingAssetIds.push(assetId);
      }
    }
    return { project: { ...project, assets }, missingAssetIds };
  } catch {
    return null;
  } finally {
    db.close();
  }
}

async function getActiveProjectId(): Promise<string | null> {
  const db = await openDb();
  try {
    const tx = db.transaction(KV_STORE, "readonly");
    const id = await getRequest(tx.objectStore(KV_STORE).get(ACTIVE_PROJECT_KEY));
    return typeof id === "string" ? id : null;
  } catch {
    return null;
  } finally {
    db.close();
  }
}

export async function loadSavedSession(): Promise<RestoredSession | null> {
  const activeId = await getActiveProjectId();
  if (activeId) {
    const restored = await loadProject(activeId);
    if (restored) return restored;
  }
  const [newest] = await listProjects();
  return newest ? loadProject(newest.id) : null;
}

export async function deleteProject(id: string): Promise<void> {
  const db = await openDb();
  let keepHashes = new Set<string>();
  try {
    const activeTx = db.transaction(KV_STORE, "readonly");
    const activeId = await getRequest(activeTx.objectStore(KV_STORE).get(ACTIVE_PROJECT_KEY));

    const deleteTx = db.transaction([KV_STORE, PROJECT_STORE], "readwrite");
    deleteTx.objectStore(PROJECT_STORE).delete(id);
    if (activeId === id) deleteTx.objectStore(KV_STORE).delete(ACTIVE_PROJECT_KEY);
    await txDone(deleteTx);

    const refsTx = db.transaction([PROJECT_STORE, ASSET_STORE], "readonly");
    const projectStore = refsTx.objectStore(PROJECT_STORE);
    const assetStore = refsTx.objectStore(ASSET_STORE);
    const [stored, keys] = await Promise.all([
      getRequest(projectStore.getAll()) as Promise<StoredProject[]>,
      getRequest(assetStore.getAllKeys()),
    ]);
    const refs = collectReferencedAssets(stored);
    keepHashes = refs.keepHashes;
    const staleKeys = keys.filter((key) => !refs.keepAssetIds.has(String(key)));
    if (staleKeys.length > 0) {
      const pruneTx = db.transaction(ASSET_STORE, "readwrite");
      const pruneStore = pruneTx.objectStore(ASSET_STORE);
      for (const key of staleKeys) pruneStore.delete(key);
      await txDone(pruneTx);
    }
  } finally {
    db.close();
  }
  await pruneMediaBlobs(keepHashes).catch(() => 0);
}

export async function saveProjectThumbnail(id: string, thumbnail: Blob): Promise<void> {
  const db = await openDb();
  try {
    const readTx = db.transaction(PROJECT_STORE, "readonly");
    const record = (await getRequest(readTx.objectStore(PROJECT_STORE).get(id))) as
      | StoredProject
      | undefined;
    if (!record) return;
    const writeTx = db.transaction(PROJECT_STORE, "readwrite");
    writeTx.objectStore(PROJECT_STORE).put({ ...record, thumbnail });
    await txDone(writeTx);
  } finally {
    db.close();
  }
}

export async function clearSavedSession(): Promise<void> {
  const activeId = await getActiveProjectId();
  if (activeId) await deleteProject(activeId);
}

'use client'

