function clipLabel(element: TimelineElement, asset?: AssetRef): string {
  if (element.type === 'text' || element.type === 'caption') return element.text
  if (element.type === 'multicam') {
    return `Multicam (${element.sources.map((s) => s.key).join(' + ')})`
  }
  return asset?.name ?? element.type
}

function isFlatFreezeVideo(element: TimelineElement): boolean {
  if (element.type !== 'video' || !element.timeMap || element.timeMap.length < 2) return false
  const value = element.timeMap[0]!.value
  return element.timeMap.every((frame) => frame.value === value)
}

function canTrimFromTimeline(element: TimelineElement): boolean {
  if (!element.groupId) return true
  return element.type === 'video' && !isFlatFreezeVideo(element)
}

function MulticamWaveform({ element, widthPx, heightPx }: { element: TimelineElement & { type: 'multicam' }; widthPx: number; heightPx: number }) {
  const source = element.sources.find((s) => s.key === element.audioSource)
  const asset = useEditorState((s) => (source ? s.project.assets[source.assetId] : undefined))
  if (!source || !asset) return null
  return (
    <AudioWaveform
      asset={asset}
      widthPx={widthPx}
      heightPx={Math.round(heightPx * 0.35)}
      trimStartMs={source.trimStartMs}
      durationMs={element.durationMs}
      timeMap={element.timeMap}
      variant="strip"
      color="rgba(255, 255, 255, 0.65)"
    />
  )
}

function tickKeyStableAcrossRetiming(cutIndex: number): string {
  return `tick-${cutIndex}`
}

function MulticamCutTicks({ element, pxPerMs }: { element: TimelineElement & { type: 'multicam' }; pxPerMs: number }) {
  const engine = useEditor()
  const layouts = useEditorState((s) => s.project.layouts)
  const dragRef = useRef<{ fromMs: number; startClientX: number } | null>(null)

  const layoutName = (layoutId: string) => layouts.find((l) => l.id === layoutId)?.name ?? '?'

  return (
    <>
      {element.angles.map((cut, i) => {
        const nextAt = element.angles[i + 1]?.atMs ?? element.durationMs
        const width = Math.max(0, (nextAt - cut.atMs) * pxPerMs)
        return (
          <span
            key={`span-${cut.atMs}`}
            className="pointer-events-none absolute bottom-0.5 z-10 truncate px-1.5 text-2xs text-overlay-foreground/75"
            style={{ left: cut.atMs * pxPerMs, maxWidth: width }}
          >
            {layoutName(cut.layoutId)}
          </span>
        )
      })}
      {element.angles.slice(1).map((cut, i) => (
        <span
          key={tickKeyStableAcrossRetiming(i)}
          title="Drag to retime the cut · ⌥-click to remove"
          className="absolute inset-y-0 z-30 w-[7px] -translate-x-1/2 cursor-col-resize"
          style={{ left: cut.atMs * pxPerMs }}
          onPointerDown={(event) => {
            event.stopPropagation()
            if (event.altKey) {
              try {
                engine.dispatch({ type: 'removeAngleCut', elementId: element.id, atMs: cut.atMs })
              } catch {}
              return
            }
            dragRef.current = { fromMs: cut.atMs, startClientX: event.clientX }
            engine.beginTransaction()
            event.currentTarget.setPointerCapture(event.pointerId)
          }}
          onPointerMove={(event) => {
            const drag = dragRef.current
            if (!drag) return
            const toMs = Math.round(drag.fromMs + (event.clientX - drag.startClientX) / pxPerMs)
            try {
              engine.dispatch({
                type: 'moveAngleCut',
                elementId: element.id,
                fromMs: drag.fromMs,
                toMs,
              })
              drag.fromMs = Math.max(1, toMs)
            } catch {}
          }}
          onPointerUp={(event) => {
            if (!dragRef.current) return
            dragRef.current = null
            engine.endTransaction()
            event.currentTarget.releasePointerCapture(event.pointerId)
          }}
        >
          <span className="absolute inset-y-0 left-1/2 w-0.5 -translate-x-1/2 bg-overlay-foreground/80" />
        </span>
      ))}
    </>
  )
}

export const Clip = memo(function Clip({ element, track, pxPerMs }: { element: TimelineElement; track: Track; pxPerMs: number }) {
  const engine = useEditor()
  const clipDrag = useClipDrag()
  const { timelineTool, layout } = useEditorUI()
  const { trimHandlePx, trimHandlesAlwaysVisible } = WORKSPACE_LAYOUT[layout]
  const selected = useEditorState((s) => s.selection.elementIds.includes(element.id))
  const multiSelected = useEditorState((s) => s.selection.elementIds.length >= 2)
  const asset = useEditorState((s) => ('assetId' in element ? s.project.assets[element.assetId] : undefined))
  const widthPx = Math.max(10, element.durationMs * pxPerMs)
  const heightPx = TRACK_HEIGHT - 8
  const label = clipLabel(element, asset)

  const beginDrag = (event: ReactPointerEvent<HTMLDivElement>) => {
    if (event.button !== 0) return
    event.stopPropagation()

    const selectionIds = engine.selection.elementIds
    const linkGroup = getLinkedElementIds(engine.project, element.id)
    const groupMembers = getGroupedElementIds(engine.project, element.id)
    const groupedIds = [...new Set(groupMembers.flatMap((id) => getLinkedElementIds(engine.project, id)))]
    if (event.shiftKey) {
      const others = selectionIds.filter((id) => !groupedIds.includes(id))
      engine.select(selected ? others : [...others, ...groupedIds])
      return
    }

    const rect = event.currentTarget.getBoundingClientRect()
    const offsetX = event.clientX - rect.left
    let mode: ClipDragMode = 'move'
    const canTrim = canTrimFromTimeline(element)
    if (canTrim && timelineTool === 'slip') mode = 'slip'
    else if (canTrim && timelineTool === 'slide') mode = 'slide'
    else if (canTrim && offsetX <= trimHandlePx) {
      mode = timelineTool === 'ripple' ? 'ripple-start' : timelineTool === 'roll' ? 'roll-start' : 'trim-start'
    } else if (canTrim && offsetX >= rect.width - trimHandlePx) {
      mode = timelineTool === 'ripple' ? 'ripple-end' : timelineTool === 'roll' ? 'roll-end' : 'trim-end'
    }
    if (element.groupId) {
      if (mode === 'roll-start' || mode === 'ripple-start') mode = 'trim-start'
      if (mode === 'roll-end' || mode === 'ripple-end') mode = 'trim-end'
    }
    const clipOnlyMode = mode !== 'move'
    const gestureSeedIds = clipOnlyMode ? linkGroup : groupedIds
    const ids =
      selected && !clipOnlyMode && selectionIds.length > groupedIds.length
        ? [...groupedIds, ...selectionIds.filter((id) => !groupedIds.includes(id))]
        : [...gestureSeedIds]
    if (!selected) engine.select([...groupedIds])

    clipDrag.begin(event, {
      mode,
      ids,
      ignoreIds: clipOnlyMode && element.groupId ? groupedIds : undefined,
      duplicateOnDrag: event.altKey && mode === 'move',
    })
  }

  const playheadInside = () => {
    const t = engine.playback.state.currentTimeMs
    return t > element.startMs && t < element.startMs + element.durationMs
  }

  const isVisual = element.type === 'video' || element.type === 'image' || element.type === 'text'
  const cutMs = element.startMs + element.durationMs
  const nextAdjacent = track.elements.find((e) => e.startMs === cutMs && e.id !== element.id)
  const transition = 'transition' in element ? element.transition : undefined
  const speed = element.type === 'video' || element.type === 'audio' ? getAverageSpeed(element) : 1
  const isReversed = (element.type === 'video' || element.type === 'audio') && element.reversed === true
  const dispatchSafe = (command: BuiltinCommand) => {
    try {
      engine.dispatch(command)
    } catch {}
  }
  const showTrimHandles = canTrimFromTimeline(element)
  const idleTrimHandleClassName = trimHandlesAlwaysVisible ? 'bg-overlay-foreground/40' : 'group-hover:bg-overlay-foreground/40'

  return (
    <ContextMenu>
      <ContextMenuTrigger
        render={
          <div
            data-mcut-clip={element.type}
            className={cn(
              'group absolute top-1 bottom-1 left-0 flex cursor-grab touch-none items-center overflow-hidden rounded-lg text-xs font-medium shadow-sm select-none active:cursor-grabbing',
              getElementUI(element.type).clipClassName,
              selected ? 'ring-2 ring-overlay-foreground' : 'ring-1 ring-overlay-foreground/10 hover:ring-overlay-foreground/30',
            )}
            style={{
              transform: `translateX(${element.startMs * pxPerMs}px)`,
              width: widthPx,
            }}
            onPointerDown={beginDrag}
            onContextMenu={() => {
              if (!selected) engine.select(getLinkedElementIds(engine.project, element.id))
            }}
            title={label}
          />
        }
      >
        {element.type === 'video' && asset && (
          <>
            <VideoFilmstrip
              asset={asset}
              widthPx={widthPx}
              heightPx={heightPx}
              trimStartMs={element.trimStartMs}
              durationMs={element.durationMs}
              timeMap={element.timeMap}
              reversed={element.reversed}
              className="opacity-90"
            />
            <AudioWaveform
              asset={asset}
              widthPx={widthPx}
              heightPx={Math.round(heightPx * 0.35)}
              trimStartMs={element.trimStartMs}
              durationMs={element.durationMs}
              timeMap={element.timeMap}
              reversed={element.reversed}
              variant="strip"
              color="rgba(255, 255, 255, 0.65)"
            />
          </>
        )}
        {element.type === 'audio' && asset && (
          <AudioWaveform
            asset={asset}
            widthPx={widthPx}
            heightPx={heightPx}
            trimStartMs={element.trimStartMs}
            durationMs={element.durationMs}
            timeMap={element.timeMap}
            reversed={element.reversed}
            color="rgba(167, 243, 208, 0.9)"
          />
        )}
        {element.type === 'audio' && <VolumeBand element={element} widthPx={widthPx} heightPx={heightPx + 8} interactive={selected} />}
        {element.type === 'multicam' && <MulticamWaveform element={element} widthPx={widthPx} heightPx={heightPx} />}
        {element.type === 'multicam' && <MulticamCutTicks element={element} pxPerMs={pxPerMs} />}
        {(element.type === 'video' || element.type === 'audio' || element.type === 'multicam') && (
          <FadeOverlay element={element} pxPerMs={pxPerMs} widthPx={widthPx} interactive={selected} />
        )}
        {selected && <KeyframeMarkers element={element} pxPerMs={pxPerMs} />}
        {(speed !== 1 || isReversed) && (
          <span className="pointer-events-none absolute top-0.5 right-2.5 z-10 rounded-sm bg-overlay/60 px-1 font-mono text-2xs text-overlay-foreground/90">
            {[speed !== 1 ? `${Number(speed.toFixed(2))}x` : null, isReversed ? '◀' : null].filter(Boolean).join(' ')}
          </span>
        )}
        {element.linkId && (
          <span
            title="Linked: selects and edits with its partner clip"
            className="pointer-events-none absolute top-0.5 left-2.5 z-10 rounded-sm bg-overlay/60 p-0.5 text-overlay-foreground/90"
          >
            <LinkIcon className="size-2.5" />
          </span>
        )}
        {transition && (
          <span
            title={nextAdjacent ? `${transition.type} → next clip` : 'Transition inactive (next clip not flush)'}
            className={cn(
              'absolute top-1/2 right-[3px] z-30 size-2 -translate-y-1/2 rotate-45 rounded-[2px]',
              nextAdjacent ? 'bg-(--snap-guide) ring-1 ring-overlay/40' : 'bg-overlay-foreground/30',
            )}
          />
        )}
        <span
          className={cn(
            'pointer-events-none relative z-10 truncate px-2',
            (element.type === 'video' || element.type === 'audio') && 'rounded-sm bg-overlay/55 py-0.5 text-2xs mx-1.5',
          )}
        >
          {label}
        </span>
        {showTrimHandles && (
          <>
            <span
              className={cn(
                'absolute inset-y-0 left-0 z-20 flex cursor-ew-resize items-center justify-center bg-overlay-foreground/0 transition-colors',
                selected ? 'bg-overlay-foreground/90' : idleTrimHandleClassName,
              )}
              style={{ width: trimHandlePx }}
            >
              <span className={cn('h-3.5 w-0.5 rounded-full', selected ? 'bg-overlay/70' : 'bg-overlay-foreground/70')} />
            </span>
            <span
              className={cn(
                'absolute inset-y-0 right-0 z-20 flex cursor-ew-resize items-center justify-center bg-overlay-foreground/0 transition-colors',
                selected ? 'bg-overlay-foreground/90' : idleTrimHandleClassName,
              )}
              style={{ width: trimHandlePx }}
            >
              <span className={cn('h-3.5 w-0.5 rounded-full', selected ? 'bg-overlay/70' : 'bg-overlay-foreground/70')} />
            </span>
          </>
        )}
      </ContextMenuTrigger>
      <ContextMenuContent>
        <ContextMenuItem disabled={!playheadInside()} onClick={() => splitSelectionAtPlayhead(engine)}>
          Split at playhead
          <span className="ml-auto pl-4 font-mono text-2xs text-muted-foreground">S</span>
        </ContextMenuItem>
        <ContextMenuItem onClick={() => duplicateElement(engine, element.id)}>Duplicate</ContextMenuItem>
        {(element.type === 'video' || element.type === 'audio') && (
          <ContextMenuItem
            onClick={() =>
              engine.dispatch({
                type: 'updateElement',
                elementId: element.id,
                patch: { muted: !element.muted },
              })
            }
          >
            {element.muted ? 'Unmute' : 'Mute'}
          </ContextMenuItem>
        )}
        {element.type === 'video' && (
          <ContextMenuItem disabled={element.muted} onClick={() => dispatchSafe({ type: 'detachAudio', elementId: element.id })}>
            Detach audio
          </ContextMenuItem>
        )}
        {element.linkId && <ContextMenuItem onClick={() => unlinkElements(engine, element.id)}>Unlink</ContextMenuItem>}
        {(element.type === 'video' || element.type === 'audio') && (
          <ContextMenuSub>
            <ContextMenuSubTrigger>Speed</ContextMenuSubTrigger>
            <ContextMenuSubContent>
              {[25, 50, 100, 150, 200, 400, -100].map((pct) => (
                <ContextMenuItem
                  key={pct}
                  onClick={() => {
                    try {
                      engine.transact(() => {
                        engine.dispatch({
                          type: 'setElementSpeed',
                          elementId: element.id,
                          speed: Math.abs(pct) / 100,
                        })
                        if (pct < 0 !== (element.reversed ?? false)) {
                          engine.dispatch({
                            type: 'updateElement',
                            elementId: element.id,
                            patch: { reversed: pct < 0 || undefined },
                          })
                        }
                      })
                    } catch {}
                  }}
                >
                  {pct}%{pct === -100 && ' (reverse)'}
                  {Math.abs(speed * (element.reversed ? -100 : 100) - pct) < 0.5 && <span className="ml-auto pl-4 text-2xs text-muted-foreground">✓</span>}
                </ContextMenuItem>
              ))}
            </ContextMenuSubContent>
          </ContextMenuSub>
        )}
        {element.type === 'multicam' && (
          <ContextMenuItem onClick={() => dispatchSafe({ type: 'flattenMulticam', elementId: element.id })}>Flatten multicam</ContextMenuItem>
        )}
        {element.type === 'video' && multiSelected && (
          <ContextMenuItem
            onClick={() => {
              const videoIds = engine.selection.elementIds.filter((id) =>
                engine.project.tracks.some((t) => t.elements.some((e) => e.id === id && e.type === 'video')),
              )
              dispatchSafe({ type: 'createMulticam', elementIds: videoIds })
            }}
          >
            Create multicam from selection
          </ContextMenuItem>
        )}
        {isVisual &&
          (transition ? (
            <ContextMenuItem onClick={() => dispatchSafe({ type: 'setTransition', elementId: element.id, transition: null })}>
              Remove transition
            </ContextMenuItem>
          ) : nextAdjacent ? (
            <ContextMenuSub>
              <ContextMenuSubTrigger>Transition into next</ContextMenuSubTrigger>
              <ContextMenuSubContent>
                {TRANSITION_TYPES.map((type) => (
                  <ContextMenuItem
                    key={type}
                    className="capitalize"
                    onClick={() =>
                      dispatchSafe({
                        type: 'setTransition',
                        elementId: element.id,
                        transition: { type, durationMs: 500 },
                      })
                    }
                  >
                    {type.replace('-', ' ')}
                  </ContextMenuItem>
                ))}
              </ContextMenuSubContent>
            </ContextMenuSub>
          ) : null)}
        <ContextMenuSeparator />
        <ContextMenuItem variant="destructive" onClick={() => removeSelection(engine)}>
          Delete
          <span className="ml-auto pl-4 font-mono text-2xs text-muted-foreground">⌫</span>
        </ContextMenuItem>
      </ContextMenuContent>
    </ContextMenu>
  )
})

'use client'

import { createElement, memo, useState } from 'react'
import { useDroppable } from '@dnd-kit/core'
import { useSortable } from '@dnd-kit/sortable'
import { CSS } from '@dnd-kit/utilities'
import { EyeIcon, EyeOffIcon, GripVerticalIcon, LayersIcon, LockIcon, LockOpenIcon, MagnetIcon, Volume2Icon, VolumeXIcon, XIcon } from '@/lib/icons'
import { useEditor, useEditorState } from '@mcut/react'
import { type Track } from '@mcut/timeline'
import { cn } from '@/lib/utils'
import { Button } from '@/components/ui/button'
import { ContextMenu, ContextMenuContent, ContextMenuItem, ContextMenuSeparator, ContextMenuTrigger } from '@/components/ui/context-menu'
import { Input } from '@/components/ui/input'
import { getElementUI } from './element-ui'
import { isSoloTrack, selectTrackElements, toggleSoloTrack } from './editor-actions'
import { type LaneDropData } from './editor-dnd'
import { useDropPreview, useEditorUI, type WorkspaceLayout } from './editor-ui'
import { formatTimecode } from './format'
import { NEW_TRACK_LANE_HEIGHT, RULER_HEIGHT, TRACK_HEIGHT } from './timeline-drag'
import { Clip } from './timeline-clip'

const GRIP_TOUCH_TARGET: Record<WorkspaceLayout, string> = {
  full: '',
  compact: 'flex h-full min-w-7 items-center justify-center',
}

function trackIcon(track: Track) {
  const first = track.elements[0]?.type
  if (!first) return LayersIcon
  return getElementUI(first).icon
}

function keepsTranscriptTimingSoNeverCompacts(track: Track): boolean {
  return track.elements.length > 0 && track.elements.every((e) => e.type === 'caption')
}

function TrackHeader({ track, gripProps }: { track: Track; gripProps?: Record<string, unknown> }) {
  const engine = useEditor()
  const { layout, timelineHeaderPx } = useEditorUI()
  const [renaming, setRenaming] = useState(false)

  return (
    <ContextMenu>
      <ContextMenuTrigger
        render={
          <div
            className="group/header sticky left-0 z-50 flex shrink-0 items-center gap-1 border-r border-foreground/10 bg-card pr-2 pl-0.5"
            style={{ width: timelineHeaderPx, height: TRACK_HEIGHT }}
            onClick={(event) => {
              if ((event.target as HTMLElement).closest('button, input')) return
              selectTrackElements(engine, track.id)
            }}
          />
        }
      >
        <button
          type="button"
          className={cn('cursor-grab touch-none text-muted-foreground/50 hover:text-muted-foreground', GRIP_TOUCH_TARGET[layout])}
          aria-label="Reorder track"
          {...gripProps}
        >
          <GripVerticalIcon className="size-3.5" />
        </button>
        {createElement(trackIcon(track), {
          className: 'size-3.5 shrink-0 text-muted-foreground',
        })}
        {renaming ? (
          <Input
            autoFocus
            defaultValue={track.name}
            className="h-5 flex-1 px-1 text-2xs"
            onBlur={(e) => {
              const name = e.target.value.trim()
              if (name && name !== track.name) {
                engine.dispatch({ type: 'renameTrack', trackId: track.id, name })
              }
              setRenaming(false)
            }}
            onKeyDown={(e) => {
              if (e.key === 'Enter') (e.target as HTMLInputElement).blur()
              if (e.key === 'Escape') setRenaming(false)
            }}
          />
        ) : (
          <span className="min-w-6 flex-1 truncate text-2xs font-medium" onDoubleClick={() => setRenaming(true)}>
            {track.name}
          </span>
        )}
        <TrackFlags track={track} layout={layout} />
      </ContextMenuTrigger>
      <ContextMenuContent>
        <ContextMenuItem onClick={() => selectTrackElements(engine, track.id)}>Select clips</ContextMenuItem>
        <ContextMenuItem onClick={() => setRenaming(true)}>Rename</ContextMenuItem>
        <ContextMenuItem
          onClick={() => {
            const index = engine.project.tracks.findIndex((t) => t.id === track.id)
            engine.dispatch({ type: 'addTrack', index: index + 1 })
          }}
        >
          Insert track above
        </ContextMenuItem>
        <ContextMenuItem
          onClick={() => {
            const index = engine.project.tracks.findIndex((t) => t.id === track.id)
            engine.dispatch({ type: 'addTrack', index })
          }}
        >
          Insert track below
        </ContextMenuItem>
        <ContextMenuSeparator />
        <ContextMenuItem variant="destructive" onClick={() => engine.dispatch({ type: 'removeTrack', trackId: track.id })}>
          Delete track
        </ContextMenuItem>
      </ContextMenuContent>
    </ContextMenu>
  )
}

function TrackFlags({ track, layout }: { track: Track; layout: WorkspaceLayout }) {
  switch (layout) {
    case 'full':
      return <TrackFlagButtons track={track} />
    case 'compact':
      return null
    default: {
      const exhaustive: never = layout
      return exhaustive
    }
  }
}

function TrackFlagButtons({ track }: { track: Track }) {
  const engine = useEditor()
  const setFlag = (patch: Partial<Pick<Track, 'muted' | 'hidden' | 'locked' | 'magnetic'>>) =>
    engine.dispatch({ type: 'setTrackFlags', trackId: track.id, ...patch })
  const timelineMagnetEnabled = useEditorState((s) => s.project.tracks.some((candidate) => candidate.magnetic))
  const solo = useEditorState(() => isSoloTrack(engine, track.id))
  const setTimelineMagnet = (magnetic: boolean) => {
    const tracks = [...engine.project.tracks]
    engine.transact(() => {
      for (const candidate of tracks) {
        if (keepsTranscriptTimingSoNeverCompacts(candidate)) continue
        if (candidate.magnetic !== magnetic) {
          engine.dispatch({ type: 'setTrackFlags', trackId: candidate.id, magnetic })
        }
      }
    })
  }

  return (
    <>
      <Button
        variant="ghost"
        size="icon-xs"
        className="size-5"
        title={track.muted ? 'Unmute track' : 'Mute track'}
        onClick={() => setFlag({ muted: !track.muted })}
      >
        {track.muted ? <VolumeXIcon className="text-destructive" /> : <Volume2Icon />}
      </Button>
      <Button
        variant="ghost"
        size="icon-xs"
        className="size-5"
        title={track.hidden ? 'Show track' : 'Hide track'}
        onClick={() => setFlag({ hidden: !track.hidden })}
      >
        {track.hidden ? <EyeOffIcon className="text-destructive" /> : <EyeIcon />}
      </Button>
      <Button
        variant="ghost"
        size="icon-xs"
        className="size-5"
        title={track.locked ? 'Unlock track' : 'Lock track'}
        onClick={() => setFlag({ locked: !track.locked })}
      >
        {track.locked ? <LockIcon className="text-destructive" /> : <LockOpenIcon />}
      </Button>
      <Button
        variant="ghost"
        size="icon-xs"
        className={cn('size-5', timelineMagnetEnabled ? 'bg-primary/20 text-primary' : 'text-muted-foreground')}
        title={timelineMagnetEnabled ? 'Disable timeline magnet' : 'Enable timeline magnet'}
        onClick={() => setTimelineMagnet(!timelineMagnetEnabled)}
      >
        <MagnetIcon />
      </Button>
      <Button
        variant="ghost"
        size="icon-xs"
        className={cn('size-5 font-mono text-2xs font-bold', solo ? 'bg-primary/20 text-primary' : 'text-muted-foreground')}
        title="Solo track (mute all others)"
        onClick={() => toggleSoloTrack(engine, track.id)}
      >
        S
      </Button>
      <Button
        variant="ghost"
        size="icon-xs"
        className="size-5 opacity-0 transition-opacity group-hover/header:opacity-100 hover:text-destructive"
        title="Delete track"
        onClick={() => engine.dispatch({ type: 'removeTrack', trackId: track.id })}
      >
        <XIcon />
      </Button>
    </>
  )
}

function LaneDropTarget({ trackId }: { trackId: string }) {
  const { setNodeRef, isOver } = useDroppable({
    id: `lane-${trackId}`,
    data: { laneTrackId: trackId } satisfies LaneDropData,
  })
  return <div ref={setNodeRef} className={cn('pointer-events-none absolute inset-0', isOver && 'bg-primary/5')} />
}

const Lane = memo(function Lane({ track, pxPerMs, contentWidth }: { track: Track; pxPerMs: number; contentWidth: number }) {
  return (
    <div
      data-mcut-lane={track.id}
      className={cn(
        'relative before:pointer-events-none before:absolute before:inset-x-0 before:inset-y-1 before:rounded-lg before:bg-foreground/[0.045]',
        track.locked && 'opacity-60',
        track.hidden && '[&_[data-mcut-clip]]:opacity-50',
      )}
      style={{ width: contentWidth, height: TRACK_HEIGHT }}
    >
      <LaneDropTarget trackId={track.id} />
      {track.elements.map((element) => (
        <Clip key={element.id} element={element} track={track} pxPerMs={pxPerMs} />
      ))}
    </div>
  )
})

export const SortableRow = memo(function SortableRow({ track, pxPerMs, contentWidth }: { track: Track; pxPerMs: number; contentWidth: number }) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({
    id: track.id,
    data: { kind: 'track', trackId: track.id },
  })
  return (
    <div ref={setNodeRef} className={cn('flex', isDragging && 'z-40 opacity-70')} style={{ transform: CSS.Transform.toString(transform), transition }}>
      <TrackHeader track={track} gripProps={{ ...attributes, ...listeners }} />
      <Lane track={track} pxPerMs={pxPerMs} contentWidth={contentWidth} />
    </div>
  )
})

export function NewTrackLane({ contentWidth, dragActive }: { contentWidth: number; dragActive: boolean }) {
  const { timelineHeaderPx } = useEditorUI()
  const { setNodeRef, isOver } = useDroppable({
    id: 'lane-new-track',
    data: { laneTrackId: 'new-track' } satisfies LaneDropData,
  })
  return (
    <div className="flex">
      <div
        className="sticky left-0 z-50 flex shrink-0 items-center justify-center border-r border-foreground/10 bg-card text-2xs text-muted-foreground"
        style={{ width: timelineHeaderPx, height: NEW_TRACK_LANE_HEIGHT }}
      >
        <span className={cn('transition-opacity', dragActive ? 'opacity-100' : 'opacity-0')}>New track</span>
      </div>
      <div
        ref={setNodeRef}
        className={cn(
          'relative before:pointer-events-none before:absolute before:inset-x-1 before:inset-y-0.5 before:rounded-lg before:border before:border-dashed before:border-primary/35 before:opacity-0 before:transition-opacity',
          dragActive && 'before:opacity-100',
          isOver && 'bg-primary/10',
        )}
        style={{ width: contentWidth, height: NEW_TRACK_LANE_HEIGHT }}
      />
    </div>
  )
}

export function DropGhostOverlay({ rows, pxPerMs }: { rows: Array<{ track: Track }>; pxPerMs: number }) {
  const ghost = useDropPreview()
  const { timelineHeaderPx } = useEditorUI()
  if (!ghost) return null
  let top = RULER_HEIGHT + 4
  let height = NEW_TRACK_LANE_HEIGHT - 8
  if (ghost.trackId !== 'new-track') {
    const row = rows.findIndex(({ track }) => track.id === ghost.trackId)
    if (row === -1) return null
    top = RULER_HEIGHT + NEW_TRACK_LANE_HEIGHT + row * TRACK_HEIGHT + 4
    height = TRACK_HEIGHT - 8
  }
  return (
    <div
      data-mcut-drop-ghost=""
      className="pointer-events-none absolute z-40 flex items-end gap-1.5 overflow-hidden rounded-lg border border-primary/80 bg-primary/25 px-1.5 py-0.5 shadow-[0_14px_32px_rgba(0,0,0,0.45),0_0_0_1px_rgba(255,255,255,0.14),inset_0_1px_0_rgba(255,255,255,0.18)] ring-1 ring-primary/35"
      style={{
        left: timelineHeaderPx + ghost.startMs * pxPerMs,
        top,
        height,
        width: Math.max(10, ghost.durationMs * pxPerMs),
      }}
    >
      <span className="truncate text-2xs font-medium text-primary">{ghost.label}</span>
      <span className="shrink-0 font-mono text-2xs text-primary/80 tabular-nums">{formatTimecode(ghost.startMs)}</span>
    </div>
  )
}

'use client'

import { useMemo, useRef, type PointerEvent as ReactPointerEvent } from 'react'
import { useEditor, useEditorState, useEngineSubscription, usePlayback, useProject } from '@mcut/react'
import { type CaptionElement } from '@mcut/timeline'
import { searchCaptions } from '@mcut/transcription'
import { useTranscriptKeywords } from './transcript-keywords'
import { useEditorUI, useSnapGuideMs } from './editor-ui'
import { formatRulerLabel } from './format'
import { RULER_HEIGHT } from './timeline-drag'

function RulerMarkers({ pxPerMs }: { pxPerMs: number }) {
  const engine = useEditor()
  const markers = useEditorState((s) => s.project.markers)
  const dragRef = useRef<{ id: string; startClientX: number; startMs: number; moved: boolean } | null>(null)

  return (
    <>
      {markers.map((marker) => (
        <span
          key={marker.id}
          title={`${marker.label ?? 'Marker'} · drag to retime · ⌥-click to remove`}
          className="absolute bottom-0 z-10 flex h-3.5 w-[11px] -translate-x-1/2 cursor-pointer justify-center"
          style={{ left: marker.timeMs * pxPerMs }}
          onPointerDown={(event) => {
            event.stopPropagation()
            if (event.button !== 0) return
            if (event.altKey) {
              try {
                engine.dispatch({ type: 'removeMarker', markerId: marker.id })
              } catch {}
              return
            }
            dragRef.current = {
              id: marker.id,
              startClientX: event.clientX,
              startMs: marker.timeMs,
              moved: false,
            }
            engine.beginTransaction()
            event.currentTarget.setPointerCapture(event.pointerId)
          }}
          onPointerMove={(event) => {
            const drag = dragRef.current
            if (!drag || drag.id !== marker.id) return
            if (Math.abs(event.clientX - drag.startClientX) > 3) drag.moved = true
            if (!drag.moved) return
            const toMs = Math.max(0, Math.round(drag.startMs + (event.clientX - drag.startClientX) / pxPerMs))
            try {
              engine.dispatch({ type: 'updateMarker', markerId: drag.id, timeMs: toMs })
            } catch {}
          }}
          onPointerUp={(event) => {
            const drag = dragRef.current
            if (!drag || drag.id !== marker.id) return
            dragRef.current = null
            engine.endTransaction()
            event.currentTarget.releasePointerCapture(event.pointerId)
            if (!drag.moved) engine.seek(marker.timeMs)
          }}
        >
          <span
            className="h-full w-[7px] rounded-[2px] rounded-b-none [clip-path:polygon(0_0,100%_0,100%_60%,50%_100%,0_60%)]"
            style={{ backgroundColor: marker.color ?? 'var(--snap-guide)' }}
          />
        </span>
      ))}
    </>
  )
}

function KeywordTicks({ pxPerMs }: { pxPerMs: number }) {
  const engine = useEditor()
  const project = useProject()
  const keywords = useTranscriptKeywords(project.id)
  const occurrences = useMemo(() => {
    if (keywords.length === 0) return []
    const captions = project.tracks.flatMap((track) => track.elements).filter((e): e is CaptionElement => e.type === 'caption')
    return keywords.flatMap((keyword) => searchCaptions(captions, keyword).map((match) => ({ keyword, timeMs: match.timeMs })))
  }, [project, keywords])
  return (
    <>
      {occurrences.map(({ keyword, timeMs }, i) => (
        <button
          key={`${keyword}-${timeMs}-${i}`}
          type="button"
          title={`“${keyword}” — click to seek`}
          className="absolute bottom-0 h-1.5 w-[3px] -translate-x-1/2 cursor-pointer rounded-t-sm bg-(--clip-caption)/70 hover:bg-(--clip-caption)"
          style={{ left: timeMs * pxPerMs }}
          onPointerDown={(event) => event.stopPropagation()}
          onClick={() => engine.seek(timeMs)}
        />
      ))}
    </>
  )
}

export function MarkerLines({ pxPerMs, height }: { pxPerMs: number; height: number }) {
  const markers = useEditorState((s) => s.project.markers)
  const { timelineHeaderPx } = useEditorUI()
  return (
    <>
      {markers.map((marker) => (
        <div
          key={marker.id}
          className="pointer-events-none absolute top-0 z-0 w-px opacity-35"
          style={{
            left: timelineHeaderPx + marker.timeMs * pxPerMs,
            height,
            backgroundColor: marker.color ?? 'var(--snap-guide)',
          }}
        />
      ))}
    </>
  )
}

export function Ruler({ pxPerMs, contentWidth }: { pxPerMs: number; contentWidth: number }) {
  const engine = useEditor()

  const seekFromEvent = (event: ReactPointerEvent<HTMLDivElement>) => {
    const rect = event.currentTarget.getBoundingClientRect()
    engine.seek(Math.max(0, (event.clientX - rect.left) / pxPerMs))
  }

  const steps = [100, 250, 500, 1000, 2000, 5000, 10_000, 30_000, 60_000, 300_000]
  const stepMs = steps.find((s) => s * pxPerMs >= 70) ?? 300_000
  const minorMs = stepMs / 5
  const minorPx = minorMs * pxPerMs
  const tickCount = Math.ceil(contentWidth / (stepMs * pxPerMs)) + 1

  return (
    <div
      className="relative cursor-col-resize bg-card"
      style={{
        width: contentWidth,
        height: RULER_HEIGHT,
        backgroundImage: `repeating-linear-gradient(to right, color-mix(in oklab, var(--foreground) 14%, transparent) 0 1px, transparent 1px ${minorPx}px)`,
        backgroundSize: `${minorPx}px 6px`,
        backgroundPosition: '0 100%',
        backgroundRepeat: 'repeat-x',
      }}
      onPointerDown={(event) => {
        event.currentTarget.setPointerCapture(event.pointerId)
        seekFromEvent(event)
      }}
      onPointerMove={(event) => {
        if (event.currentTarget.hasPointerCapture(event.pointerId)) seekFromEvent(event)
      }}
      onPointerUp={(event) => event.currentTarget.releasePointerCapture(event.pointerId)}
    >
      {Array.from({ length: tickCount }, (_, i) => (
        <div
          key={i}
          className="absolute top-0 h-full border-l border-foreground/15 pl-1 pt-1 font-mono text-2xs leading-none text-muted-foreground select-none"
          style={{ left: i * stepMs * pxPerMs }}
        >
          {formatRulerLabel(i * stepMs)}
        </div>
      ))}
      <RulerMarkers pxPerMs={pxPerMs} />
      <KeywordTicks pxPerMs={pxPerMs} />
    </div>
  )
}

export function Playhead({ pxPerMs, height }: { pxPerMs: number; height: number }) {
  const engine = useEditor()
  const currentTimeMs = usePlayback((s) => s.currentTimeMs)
  const { timelineScrollRef, timelineHeaderPx } = useEditorUI()

  useEngineSubscription(engine.playback, (playback) => {
    const scroller = timelineScrollRef.current
    if (!playback.isPlaying || !scroller) return
    const playheadX = timelineHeaderPx + playback.currentTimeMs * pxPerMs
    const viewLeft = scroller.scrollLeft + timelineHeaderPx
    const viewRight = scroller.scrollLeft + scroller.clientWidth - 40
    if (playheadX < viewLeft || playheadX > viewRight) {
      scroller.scrollLeft = Math.max(0, playheadX - timelineHeaderPx - 80)
    }
  })

  return (
    <div className="pointer-events-none absolute top-0 z-10 w-px bg-primary" style={{ left: timelineHeaderPx + currentTimeMs * pxPerMs, height }}>
      <div className="absolute -top-px -left-[5.5px] flex h-4 w-3 items-start justify-center">
        <div className="h-3 w-3 rounded-[3px] rounded-b-none bg-primary [clip-path:polygon(0_0,100%_0,100%_60%,50%_100%,0_60%)]" />
      </div>
    </div>
  )
}

export function SnapGuide({ pxPerMs, height }: { pxPerMs: number; height: number }) {
  const snapGuideMs = useSnapGuideMs()
  const { timelineHeaderPx } = useEditorUI()
  if (snapGuideMs === null) return null
  return <div className="pointer-events-none absolute top-0 z-30 w-px bg-(--snap-guide)" style={{ left: timelineHeaderPx + snapGuideMs * pxPerMs, height }} />
}

'use client'

import { useCallback, useMemo, useState } from 'react'
import { useMutation } from '@tanstack/react-query'
import { ChevronDownIcon, ChevronUpIcon, LinkIcon, PlusIcon, ScissorsIcon, SearchIcon, SparklesIcon, XIcon } from '@/lib/icons'
import { toast } from 'sonner'
import { extractAudioToWav } from '@mcut/media'
import { useEditor, usePlayback, useProject, useSelectedElement } from '@mcut/react'
import { isElementActiveAt, type CaptionElement, type ElementAudioSource, type Project, resolveElementAudioSource } from '@mcut/timeline'
import {
  buildApplyCaptionsCommand,
  mapCaptionWords,
  mergeCaptions,
  replaceAllMatches,
  replaceMatch,
  retypeWord,
  searchCaptions,
  splitCaptionAtWord,
  type TranscriptMatch,
  type TranscriptResult,
} from '@mcut/transcription'
import { cn } from '@/lib/utils'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { ScrollArea } from '@/components/ui/scroll-area'
import { EmptyState, PanelHeader, PanelSectionLabel, Spinner } from './editor-primitives'
import { formatTimecode } from './format'
import { addTranscriptKeyword, attachTranscriptSearch, removeTranscriptKeyword, useTranscriptKeywords } from './transcript-keywords'

export interface TranscriptPanelProps {
  className?: string
  transcribe?: (audio: Blob) => Promise<TranscriptResult>
}

function captionsOf(project: Project): CaptionElement[] {
  return project.tracks
    .flatMap((track) => track.elements)
    .filter((e): e is CaptionElement => e.type === 'caption')
    .sort((a, b) => a.startMs - b.startMs)
}

function matchedWordIndices(captionId: string, matches: TranscriptMatch[]): Set<number> {
  const indices = new Set<number>()
  for (const match of matches) {
    if (match.captionId !== captionId) continue
    if (match.firstWord === undefined || match.lastWord === undefined) continue
    for (let i = match.firstWord; i <= match.lastWord; i++) indices.add(i)
  }
  return indices
}

interface WordSelection {
  captionId: string
  wordIndex: number
}

export function TranscriptPanel({ className, transcribe }: TranscriptPanelProps) {
  const engine = useEditor()
  const project = useProject()
  const captions = useMemo(() => captionsOf(project), [project])

  const [query, setQuery] = useState('')
  const [replacement, setReplacement] = useState('')
  const [activeIndex, setActiveIndex] = useState(0)
  const [selectedWord, setSelectedWord] = useState<WordSelection | null>(null)
  const [keywordDraft, setKeywordDraft] = useState('')

  const keywords = useTranscriptKeywords(project.id)
  const trimmedQuery = query.trim()
  const matches = useMemo(() => searchCaptions(captions, trimmedQuery), [captions, trimmedQuery])
  const keywordMatches = useMemo(() => keywords.flatMap((keyword) => searchCaptions(captions, keyword)), [captions, keywords])
  const active = matches.length > 0 ? matches[Math.min(activeIndex, matches.length - 1)]! : null

  const [navigated, setNavigated] = useState(false)
  const goTo = (index: number) => {
    if (matches.length === 0) return
    const wrapped = ((index % matches.length) + matches.length) % matches.length
    setNavigated(true)
    setActiveIndex(wrapped)
    engine.seek(matches[wrapped]!.timeMs)
  }
  const step = (direction: 1 | -1) => {
    goTo(navigated ? activeIndex + direction : activeIndex)
  }

  const replaceCurrent = () => {
    if (!active) return
    const caption = captions.find((c) => c.id === active.captionId)
    if (!caption) return
    const patch = replaceMatch(caption, active, replacement)
    try {
      engine.dispatch({
        type: 'updateElement',
        elementId: caption.id,
        patch: { text: patch.text, words: patch.words ?? [] },
      })
    } catch {
      return
    }
    setActiveIndex((i) => i)
  }

  const replaceEverywhere = () => {
    const patches = replaceAllMatches(captions, trimmedQuery, replacement)
    if (patches.length === 0) return
    engine.transact(() => {
      for (const patch of patches) {
        const caption = captions.find((c) => c.id === patch.captionId)
        if (!caption) continue
        try {
          engine.dispatch({
            type: 'updateElement',
            elementId: caption.id,
            patch: { text: patch.text, words: patch.words ?? [] },
          })
        } catch {}
      }
    })
    toast.success(`Replaced ${matches.length} ${matches.length === 1 ? 'match' : 'matches'}`)
  }

  const retranscribe = useRetranscribe(transcribe)

  return (
    <div className={cn('flex h-full min-h-0 flex-col', className)}>
      <PanelHeader>
        <PanelSectionLabel>Transcript</PanelSectionLabel>
      </PanelHeader>

      <div className="flex shrink-0 flex-col gap-2 px-3 pb-2">
        <div className="flex items-center gap-1">
          <div className="relative flex-1">
            <SearchIcon className="pointer-events-none absolute top-1/2 left-2 size-3.5 -translate-y-1/2 text-muted-foreground" />
            <Input
              ref={attachTranscriptSearch}
              value={query}
              placeholder="Find in transcript…"
              className="h-7 pl-7 text-xs"
              onChange={(event) => {
                setQuery(event.target.value)
                setActiveIndex(0)
                setNavigated(false)
              }}
              onKeyDown={(event) => {
                if (event.key === 'Enter') {
                  event.preventDefault()
                  step(event.shiftKey ? -1 : 1)
                }
                if (event.key === 'Escape') event.currentTarget.blur()
              }}
            />
          </div>
          <span className="w-12 text-center font-mono text-2xs text-muted-foreground">
            {trimmedQuery ? `${matches.length === 0 ? 0 : Math.min(activeIndex, matches.length - 1) + 1}/${matches.length}` : ''}
          </span>
          <Button variant="ghost" size="icon-xs" title="Previous match (⇧↵)" disabled={matches.length === 0} onClick={() => step(-1)}>
            <ChevronUpIcon />
          </Button>
          <Button variant="ghost" size="icon-xs" title="Next match (↵)" disabled={matches.length === 0} onClick={() => step(1)}>
            <ChevronDownIcon />
          </Button>
        </div>

        {trimmedQuery && (
          <div className="flex items-center gap-1">
            <Input
              value={replacement}
              placeholder="Replace with…"
              className="h-7 flex-1 text-xs"
              onChange={(event) => setReplacement(event.target.value)}
              onKeyDown={(event) => {
                if (event.key === 'Enter') {
                  event.preventDefault()
                  replaceCurrent()
                }
              }}
            />
            <Button variant="outline" size="xs" disabled={!active} onClick={replaceCurrent}>
              Replace
            </Button>
            <Button variant="outline" size="xs" disabled={matches.length === 0} onClick={replaceEverywhere}>
              All
            </Button>
          </div>
        )}

        <div className="flex flex-col gap-1">
          <PanelSectionLabel>Keywords</PanelSectionLabel>
          <div className="flex flex-wrap items-center gap-1">
            {keywords.map((keyword) => (
              <button
                key={keyword}
                type="button"
                title={`${countOf(captions, keyword)} occurrences · click to remove`}
                className="flex items-center gap-1 rounded-full bg-(--clip-caption)/15 px-2 py-0.5 text-2xs text-(--clip-caption) hover:bg-(--clip-caption)/25"
                onClick={() => removeTranscriptKeyword(project.id, keyword)}
              >
                {keyword}
                <span className="font-mono opacity-70">{countOf(captions, keyword)}</span>
                <XIcon className="size-2.5" />
              </button>
            ))}
            <form
              className="flex items-center gap-1"
              onSubmit={(event) => {
                event.preventDefault()
                if (keywordDraft.trim()) {
                  addTranscriptKeyword(project.id, keywordDraft)
                  setKeywordDraft('')
                }
              }}
            >
              <Input value={keywordDraft} placeholder="Add keyword" className="h-6 w-28 text-2xs" onChange={(event) => setKeywordDraft(event.target.value)} />
              <Button type="submit" variant="ghost" size="icon-xs" title="Add keyword (marks occurrences on the timeline ruler)">
                <PlusIcon />
              </Button>
            </form>
          </div>
        </div>

        {transcribe && (
          <Button
            variant="outline"
            size="xs"
            disabled={retranscribe.isPending || !retranscribe.eligible}
            title={retranscribe.eligible ? "Re-run transcription on the selected clip's time range only" : 'Select a video, audio, or multicam clip first'}
            onClick={() => retranscribe.mutate()}
          >
            {retranscribe.isPending ? <Spinner /> : <SparklesIcon />}
            {retranscribe.isPending ? 'Re-transcribing…' : 'Re-transcribe selected clip'}
          </Button>
        )}
      </div>

      {captions.length === 0 ? (
        <EmptyState className="mx-3 mb-3 flex-1" icon={SearchIcon} description="No transcript yet. Auto-caption a clip in the Captions tab first." />
      ) : (
        <ScrollArea className="min-h-0 flex-1 scroll-mask-b">
          <div className="flex flex-col gap-0.5 px-3 pb-3">
            {captions.map((caption, index) => (
              <TranscriptRow
                key={caption.id}
                caption={caption}
                previous={index > 0 ? captions[index - 1]! : null}
                activeMatch={active?.captionId === caption.id ? active : null}
                queryMatches={matches}
                keywordMatches={keywordMatches}
                selectedWord={selectedWord?.captionId === caption.id ? selectedWord : null}
                onSelectWord={setSelectedWord}
              />
            ))}
          </div>
        </ScrollArea>
      )}
    </div>
  )
}

function countOf(captions: CaptionElement[], keyword: string): number {
  return searchCaptions(captions, keyword).length
}

function useRetranscribe(transcribe: TranscriptPanelProps['transcribe']) {
  const engine = useEditor()
  const selected = useSelectedElement()
  const source = selected ? resolveElementAudioSource(engine.project, selected.element.id) : null
  const mutation = useMutation({
    mutationFn: async () => {
      if (!transcribe || !source) throw new Error('Select a video, audio, or multicam clip first.')
      const wav = await extractAudioToWav(source.asset.src)
      if (!wav) throw new Error(`"${source.asset.name ?? source.asset.id}" has no audio track.`)
      const result = await transcribe(wav)
      return { result, source }
    },
    onSuccess: ({ result, source }: { result: TranscriptResult; source: ElementAudioSource }) => {
      const start = source.timelineStartMs
      const end = source.timelineStartMs + source.timelineDurationMs
      engine.transact(() => {
        for (const caption of captionsOf(engine.project)) {
          if (caption.startMs < end && caption.startMs + caption.durationMs > start) {
            try {
              engine.dispatch({ type: 'removeElement', elementId: caption.id })
            } catch {}
          }
        }
        engine.dispatch(
          buildApplyCaptionsCommand(result, {
            replace: false,
            timeOffsetMs: source.timelineStartMs,
            sourceStartMs: source.sourceStartMs,
            sourceEndMs: source.sourceEndMs,
          }),
        )
      })
      toast.success('Clip re-transcribed')
    },
    onError: (error) => {
      toast.error(error instanceof Error ? error.message : 'Transcription failed')
    },
  })
  return { ...mutation, eligible: !!source && !!transcribe }
}

function TranscriptRow({
  caption,
  previous,
  activeMatch,
  queryMatches,
  keywordMatches,
  selectedWord,
  onSelectWord,
}: {
  caption: CaptionElement
  previous: CaptionElement | null
  activeMatch: TranscriptMatch | null
  queryMatches: TranscriptMatch[]
  keywordMatches: TranscriptMatch[]
  selectedWord: WordSelection | null
  onSelectWord: (selection: WordSelection | null) => void
}) {
  const engine = useEditor()
  const playbackActive = usePlayback((s) => isElementActiveAt(caption, s.currentTimeMs))
  const mapped = useMemo(() => mapCaptionWords(caption), [caption])
  const queryWords = useMemo(() => matchedWordIndices(caption.id, queryMatches), [caption.id, queryMatches])
  const keywordWords = useMemo(() => matchedWordIndices(caption.id, keywordMatches), [caption.id, keywordMatches])
  const activeWords = useMemo(() => (activeMatch ? matchedWordIndices(caption.id, [activeMatch]) : new Set<number>()), [caption.id, activeMatch])
  const [editing, setEditing] = useState<number | null>(null)
  const revealActive = useCallback(
    (node: HTMLDivElement | null) => {
      if (node && activeMatch) node.scrollIntoView({ block: 'nearest', behavior: 'smooth' })
    },
    [activeMatch],
  )

  const dispatchContent = (patch: { text: string; words?: { text: string; startMs: number; endMs: number }[] }) => {
    try {
      engine.dispatch({
        type: 'updateElement',
        elementId: caption.id,
        patch: { text: patch.text, words: patch.words ?? [] },
      })
    } catch {}
  }

  const splitAt = (wordIndex: number) => {
    const result = splitCaptionAtWord(caption, wordIndex)
    if (!result) return
    const location = engine.project.tracks.find((t) => t.elements.some((e) => e.id === caption.id))
    if (!location) return
    engine.transact(() => {
      engine.dispatch({
        type: 'updateElement',
        elementId: caption.id,
        patch: { text: result.left.text, words: result.left.words, durationMs: result.left.durationMs },
      })
      engine.dispatch({
        type: 'addElement',
        trackId: location.id,
        element: { type: 'caption', style: caption.style, ...result.right },
      })
    })
    onSelectWord(null)
  }

  const mergeUp = () => {
    if (!previous) return
    const merged = mergeCaptions(previous, caption)
    engine.transact(() => {
      engine.dispatch({ type: 'removeElement', elementId: caption.id })
      engine.dispatch({
        type: 'updateElement',
        elementId: previous.id,
        patch: {
          text: merged.text,
          words: merged.words ?? [],
          startMs: merged.startMs,
          durationMs: merged.durationMs,
        },
      })
    })
    onSelectWord(null)
  }

  return (
    <div
      ref={revealActive}
      className={cn('group rounded-lg p-2 transition-colors hover:bg-muted/60', playbackActive && 'bg-primary/10', activeMatch && 'ring-1 ring-primary/40')}
    >
      <div className="flex items-center gap-1">
        <button
          type="button"
          className="cursor-pointer font-mono text-2xs text-muted-foreground hover:text-foreground"
          title="Seek to caption"
          onClick={() => engine.seek(caption.startMs)}
        >
          {formatTimecode(caption.startMs)}
        </button>
        <div className="flex-1" />
        {previous && (
          <Button
            variant="ghost"
            size="icon-xs"
            title="Merge with previous caption"
            className="opacity-0 transition-opacity group-focus-within:opacity-100 group-hover:opacity-100"
            onClick={mergeUp}
          >
            <LinkIcon />
          </Button>
        )}
      </div>

      {mapped ? (
        <p className="flex flex-wrap gap-x-1 gap-y-0.5 p-1 text-xs leading-5">
          {mapped.map((m, i) => {
            if (editing === i) {
              return (
                <WordEditor
                  key={`${i}-edit`}
                  initial={m.word.text}
                  onCommit={(value) => {
                    setEditing(null)
                    if (value && value !== m.word.text) {
                      const patch = retypeWord(caption, i, value)
                      if (patch) dispatchContent(patch)
                    }
                  }}
                  onCancel={() => setEditing(null)}
                />
              )
            }
            const isSelected = selectedWord?.wordIndex === i
            return (
              <span key={i} className="relative">
                <button
                  type="button"
                  title="Click to seek · double-click to retype"
                  className={cn(
                    'cursor-pointer rounded px-0.5 hover:bg-muted',
                    keywordWords.has(i) && 'bg-(--clip-caption)/20 text-(--clip-caption)',
                    queryWords.has(i) && 'bg-primary/15',
                    activeWords.has(i) && 'bg-primary/30',
                    isSelected && 'ring-1 ring-primary',
                  )}
                  onClick={() => {
                    engine.seek(caption.startMs + m.word.startMs)
                    onSelectWord(isSelected ? null : { captionId: caption.id, wordIndex: i })
                  }}
                  onDoubleClick={() => {
                    onSelectWord(null)
                    setEditing(i)
                  }}
                >
                  {m.word.text}
                </button>
                {isSelected && i > 0 && (
                  <span className="absolute -top-6 left-0 z-10 flex gap-0.5 rounded-md border bg-popover p-0.5 shadow-sm">
                    <Button variant="ghost" size="icon-xs" title="Split caption before this word" onClick={() => splitAt(i)}>
                      <ScissorsIcon />
                    </Button>
                  </span>
                )}
              </span>
            )
          })}
        </p>
      ) : (
        <p
          className="cursor-pointer p-1 text-xs leading-5 text-muted-foreground"
          title="No word timings (edited caption) — click to seek"
          onClick={() => engine.seek(caption.startMs)}
        >
          {caption.text}
        </p>
      )}
    </div>
  )
}

function WordEditor({ initial, onCommit, onCancel }: { initial: string; onCommit: (value: string) => void; onCancel: () => void }) {
  const [value, setValue] = useState(initial)
  return (
    <input
      autoFocus
      value={value}
      size={Math.max(3, value.length)}
      className="rounded border border-primary bg-input/50 px-0.5 text-xs outline-none"
      onChange={(event) => setValue(event.target.value)}
      onBlur={() => onCommit(value.trim())}
      onKeyDown={(event) => {
        if (event.key === 'Enter') onCommit(value.trim())
        if (event.key === 'Escape') onCancel()
      }}
    />
  )
}

'use client'

import { useSyncExternalStore } from 'react'

const storageKey = (projectId: string) => `mcut:transcript:keywords:v1:${projectId}`

const listeners = new Set<() => void>()
const cache = new Map<string, string[]>()
const EMPTY: string[] = []

function notify(): void {
  for (const listener of listeners) listener()
}

function read(projectId: string): string[] {
  if (typeof window === 'undefined') return EMPTY
  let value = cache.get(projectId)
  if (!value) {
    try {
      const raw = JSON.parse(window.localStorage.getItem(storageKey(projectId)) ?? '[]')
      value = Array.isArray(raw) ? raw.filter((k): k is string => typeof k === 'string') : []
    } catch {
      value = []
    }
    cache.set(projectId, value)
  }
  return value
}

export function getTranscriptKeywords(projectId: string): string[] {
  return read(projectId)
}

export function setTranscriptKeywords(projectId: string, keywords: string[]): void {
  const cleaned = [...new Set(keywords.map((k) => k.trim()).filter((k) => k.length > 0))]
  cache.set(projectId, cleaned)
  try {
    window.localStorage.setItem(storageKey(projectId), JSON.stringify(cleaned))
  } catch {}
  notify()
}

export function addTranscriptKeyword(projectId: string, keyword: string): void {
  setTranscriptKeywords(projectId, [...read(projectId), keyword])
}

export function removeTranscriptKeyword(projectId: string, keyword: string): void {
  setTranscriptKeywords(
    projectId,
    read(projectId).filter((k) => k !== keyword),
  )
}

function subscribe(onChange: () => void): () => void {
  listeners.add(onChange)
  return () => listeners.delete(onChange)
}

export function useTranscriptKeywords(projectId: string): string[] {
  return useSyncExternalStore(
    subscribe,
    () => read(projectId),
    () => EMPTY,
  )
}

let searchInput: HTMLInputElement | null = null
let pendingFocus = false

function focusSearch(input: HTMLInputElement): void {
  input.focus()
  input.select()
}

export function focusTranscriptSearch(): void {
  if (searchInput) focusSearch(searchInput)
  else pendingFocus = true
}

export function attachTranscriptSearch(input: HTMLInputElement | null): void {
  searchInput = input
  if (input && pendingFocus) {
    pendingFocus = false
    focusSearch(input)
  }
}

