        kind: 'checkbox',
        id: 'view.toggle-auto-crossfade',
        label: 'Auto-crossfade',
        checked: (ui) => ui.autoCrossfade,
      },
      { kind: 'checkbox', id: 'view.toggle-theme', label: 'Dark theme', checked: (ui) => ui.theme === 'dark' },
      'separator',
      { id: 'view.fullscreen' },
      { id: 'view.reset-layout' },
    ],
  },
  {
    label: 'Tools',
    entries: [
      { id: 'edit.add-text' },
      { id: 'edit.add-track' },
      { id: 'multicam.create', label: 'Create multicam from selection' },
      'separator',
      { id: 'help.command-palette' },
    ],
  },
]

function MenuEntryItem({ entry, context }: { entry: MenuEntry; context: ActionContext }) {
  if (entry === 'separator') return <DropdownMenuSeparator />
  const action = getEditorAction(entry.id)
  if (!action) return null
  const label = entry.label ?? action.label
  const shortcut = formatShortcut(action.shortcut)
  const disabled = !isActionEnabled(action, context)

  if (entry.kind === 'checkbox') {
    return (
      <DropdownMenuCheckboxItem checked={entry.checked(context.ui)} disabled={disabled} onCheckedChange={() => runEditorAction(action, context)}>
        {label}
      </DropdownMenuCheckboxItem>
    )
  }
  return (
    <DropdownMenuItem disabled={disabled} onClick={() => runEditorAction(action, context)}>
      {label}
      {shortcut && <DropdownMenuShortcut>{shortcut}</DropdownMenuShortcut>}
    </DropdownMenuItem>
  )
}

export function MainMenu() {
  const engine = useEditor()
  const ui = useEditorUI()
  useLiveActionEnabledStates()
  const context: ActionContext = { engine, ui, clipboard: editorClipboard }
  const shortcutsAction = getEditorAction('help.shortcuts')

  return (
    <DropdownMenu>
      <DropdownMenuTrigger render={<Button variant="ghost" aria-label="Main menu" className="mr-1 h-9 gap-1 px-1.5 hover:bg-foreground/5" />}>
        <BrandMark className="text-3xl" />
        <ChevronDownIcon className="size-3.5 text-muted-foreground" />
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start" className="w-auto min-w-48">
        <DropdownMenuItem render={<Link href="/tools" />}>MCP tools</DropdownMenuItem>
        <DropdownMenuSeparator />
        {MENU_SECTIONS.map((section) => (
          <DropdownMenuSub key={section.label}>
            <DropdownMenuSubTrigger>{section.label}</DropdownMenuSubTrigger>
            <DropdownMenuSubContent className="min-w-56">
              {section.entries.map((entry, index) => (
                <MenuEntryItem key={entry === 'separator' ? `separator-${index}` : entry.id} entry={entry} context={context} />
              ))}
            </DropdownMenuSubContent>
          </DropdownMenuSub>
        ))}
        <DropdownMenuSeparator />
        {shortcutsAction && (
          <DropdownMenuItem onClick={() => runEditorAction(shortcutsAction, context)}>
            Keyboard shortcuts
            <DropdownMenuShortcut>{formatShortcut(shortcutsAction.shortcut)}</DropdownMenuShortcut>
          </DropdownMenuItem>
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

'use client'

import { toast } from 'sonner'
import { createAsset } from '@mcut/media'
import type { EditorEngine } from '@mcut/timeline'
import type { AssetRef } from '@mcut/timeline'

export type OnAssetImported = (asset: AssetRef, file: File) => void

export async function importMediaFiles(engine: EditorEngine, files: File[], onAssetImported?: OnAssetImported): Promise<AssetRef[]> {
  const imported: AssetRef[] = []
  for (const file of files) {
    try {
      const asset = await createAsset({ kind: 'blob', blob: file, name: file.name })
      engine.dispatch({ type: 'addAsset', asset }, { history: false })
      imported.push(asset)
      onAssetImported?.(asset, file)
    } catch (error) {
      console.error(error)
      toast.error(`Could not import ${file.name}`)
    }
  }
  return imported
}

export function pickFiles(accept: string, multiple = true): Promise<File[]> {
  return new Promise((resolve) => {
    const input = document.createElement('input')
    input.type = 'file'
    input.accept = accept
    input.multiple = multiple
    input.onchange = () => resolve(Array.from(input.files ?? []))
    input.oncancel = () => resolve([])
    input.click()
  })
}

'use client'

import { toast } from 'sonner'
import { loadMediaBlob } from '@mcut/media'
import { parseProject, type EditorEngine, type Project } from '@mcut/timeline'
import { pickFiles } from './media-import'

function downloadText(text: string, filename: string, type: string) {
  const url = URL.createObjectURL(new Blob([text], { type }))
  const anchor = document.createElement('a')
  anchor.href = url
  anchor.download = filename
  anchor.click()
  setTimeout(() => URL.revokeObjectURL(url), 10_000)
}

export function saveProjectToFile(project: Project): void {
  const slug = (project.name || 'untitled').trim().replace(/[\\/:*?"<>|]+/g, '-')
  downloadText(JSON.stringify(project, null, 2), `${slug}.mcut.json`, 'application/json')
  toast.success('Project file saved — media re-links by content hash on this device')
}

export async function openProjectFromFile(engine: EditorEngine): Promise<void> {
  const [file] = await pickFiles('.json,application/json', false)
  if (!file) return
  let project: Project
  try {
    project = parseProject(JSON.parse(await file.text()))
  } catch (error) {
    console.error(error)
    toast.error(`${file.name} is not a valid mcut project file`)
    return
  }

  const missing: string[] = []
  const assets = { ...project.assets }
  for (const [id, asset] of Object.entries(assets)) {
    const blob = asset.hash ? await loadMediaBlob(asset.hash).catch(() => null) : null
    if (blob) {
      assets[id] = { ...asset, src: URL.createObjectURL(blob) }
    } else if (asset.src.startsWith('blob:')) {
      missing.push(id)
    }
  }

  engine.loadProject({ ...project, assets })
  if (missing.length > 0) {
    toast.warning(`${missing.length} media file(s) are not on this device — re-import them to relink.`)
  } else {
    toast.success(`Opened ${project.name}`)
  }
}

'use client'

import { toast } from 'sonner'
import { readDesktopApi, type DesktopApi, type DesktopErrorShape, type DesktopResult, type MenuAction, type UpdateState } from '@mcut/desktop-ipc'
import { loadMediaBlob, preloadMediabunny } from '@mcut/media'
import type { Project } from '@mcut/timeline'
import type { DesktopUpdates, StudioHost } from './studio-host'

declare global {
  interface WindowEventMap {
    'mcut:run-action': CustomEvent<string>
  }
}

const MENU_ACTION_IDS: Record<MenuAction, string> = {
  'project.open': 'file.open',
  'project.save': 'file.save',
  'project.saveAs': 'file.save-as',
}

function reportFailure(error: DesktopErrorShape): void {
  if (error.code !== 'cancelled') toast.error(error.message)
}

async function relinkAssets(project: Project): Promise<{ project: Project; missing: number }> {
  let missing = 0
  const assets = { ...project.assets }
  for (const [id, asset] of Object.entries(assets)) {
    const blob = asset.hash ? await loadMediaBlob(asset.hash).catch(() => null) : null
    if (blob) {
      assets[id] = { ...asset, src: URL.createObjectURL(blob) }
      continue
    }
    if (asset.src.startsWith('blob:')) missing += 1
  }
  return { project: { ...project, assets }, missing }
}

function createDesktopUpdates(api: DesktopApi): DesktopUpdates {
  let state: UpdateState = { phase: 'idle' }
  const listeners = new Set<() => void>()
  const assign = (next: UpdateState): void => {
    state = next
    for (const listener of listeners) listener()
  }
  api.update.onState(assign)

  const apply = async (result: Promise<DesktopResult<UpdateState>>): Promise<void> => {
    const outcome = await result
    if (!outcome.ok) return reportFailure(outcome.error)
    assign(outcome.value)
  }

  return {
    get: () => state,
    subscribe: (listener) => {
      listeners.add(listener)
      return () => {
        listeners.delete(listener)
      }
    },
    download: () => apply(api.update.download()),
    install: () => apply(api.update.install()),
  }
}

export function createDesktopHost(): StudioHost | null {
  const api = readDesktopApi()
  if (api === null) return null
  requestIdleCallback(() => void preloadMediabunny())
  const filePaths = new Map<string, string>()

  api.onMenu((action) => {
    window.dispatchEvent(new CustomEvent('mcut:run-action', { detail: MENU_ACTION_IDS[action] }))
  })

  const save = async (project: Project, path: string | null): Promise<void> => {
    const saved = await api.projects.save({ project, path })
    if (!saved.ok) return reportFailure(saved.error)
    filePaths.set(project.id, saved.value.path)
    toast.success(`Saved ${saved.value.path}`)
  }

  return {
    openProject: async (engine) => {
      const opened = await api.projects.open()
      if (!opened.ok) return reportFailure(opened.error)
      const { project, missing } = await relinkAssets(opened.value.project)
      engine.loadProject(project)
      filePaths.set(project.id, opened.value.path)
      if (missing > 0) {
        toast.warning(`${missing} media file(s) are not on this device. Re-import them to relink.`)
      } else {
        toast.success(`Opened ${project.name}`)
      }
    },
    saveProject: (project) => save(project, filePaths.get(project.id) ?? null),
    saveProjectAs: (project) => save(project, null),
    transcriptionSettings: {
      isConfigured: async () => {
        const info = await api.info()
        return info.ok && info.value.transcription.configured
      },
      setKey: async (key) => {
        const result = await api.setTranscriptionKey(key)
        if (!result.ok) {
          reportFailure(result.error)
          return false
        }
        return result.value.configured
      },
    },
    windowChrome: api.platform === 'darwin' ? 'mac' : 'linux',
    updates: createDesktopUpdates(api),
  }
}
